                {
                    { 141, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أغنية خيال علمي...\nهذا هو تقريبًا أدق وصف لهذه الأغنية القديمة التي قدمها الثنائي الأمريكي \"زاجر وإيفانز\" عام 1969. لقد حققت نجاحًا هائلًا آنذاك، حتى أنه كان بإمكانك سماعها طوال اليوم على محطات الراديو في مصر. ولوقت طويل، كانت هذه المقطوعة الموسيقية هي الخلفية الصوتية لأي عمل درامي يتعلق بالمستقبلية.\nتتخيل الأغنية حالة الإنسانية في عام 2525، ثم تقفز بزيادات قدرها 1010 سنة مع كل مقطع جديد. تُظهر لنا كيف ستتقدم البشرية، لكن في اتجاه معاكس لليوتوبيا، حيث يتحول البشر إلى كائنات شبيهة بالآلات المبرمجة. تناقش الأغنية ما يناقشه كل كاتب معاصر في مجال الخيال العلمي، مع نفس اللمسة من التشاؤم والقلق على مصير هذا الكوكب الجميل الذي هدّرنا موارده دون حساب.\nاللحن سريع ومبهج، لكنه ينقل أيضًا إحساسًا بالرهبة والغربة؛ تشعر وكأنك في سباق محموم مع آلة زمن مجنونة نحو نهاية مجهولة ومظلمة، دون رجعة؛ فأنت تندفع بلا توقف نحو الثقب الأسود.\n(الكتاب عبارة عن مجموعة من المقالات يكتب فيها الدكتور أحمد خالد توفيق عن الأغاني التي يحبها ويترجمها.)", "/images/products/9789778202243.webp", "9789778202243", "نشوات قديمة", 432, 290m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 142, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتألف رواية \"الغرفة 207\" من سلسلة قصص قصيرة وقعت مع أشخاص مختلفين في أوقات متباينة، والربط المشترك بينها هو وقوع جميعها في نفس المكان: الغرفة 207 في فندق بمرسى مطروح، مصر.\nتُلاحظ هذه الأحداث وتُروى على لسان العم جمال، الذي يجمع هذه القصص من خلال خبرته كمستقبل في الفندق، مما يخلق رابطًا خاصًا بينه وبين الغرفة، ومع كل العجائب والطرائف التي تحدث فيها، تأسر العقل وتوقظ الفضول.", "/images/products/9789778200270.webp", "9789778200270", "سر الغرفة 207", 220, 170m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 143, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يقوم 12 صحفيًا بإعداد تقرير عن ساحر يخدع الناس، خاصة الفقراء، وينتهز كل ما يستطيع منهم بوعده لهم بحياة أفضل أو بحل لمعظم مشاكلهم.\nوبعد أن كشفوا الحقيقة، وُضع الساحر في السجن، ثم انتحر، تاركًا رسالة قصيرة لكل واحد من هؤلاء الـ12 صحفيًا، تتألف من جملة واحدة:\n«برجك (أبراجك الفلكية) سينتقم من أجلي.»\nوكلٌ منهم يواجه الموت بطريقة مختلفة وفقًا لبرجه.", "/images/products/9789778200164.webp", "9789778200164", "حظك اليوم", 130, 130m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 144, "أحمد خالد توفيق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة قصص قصيرة ترتبط بفكرة واحدة: الصداقة بين شخصين.\nإحدى الشخصيات تتميز بجسد مفتول العضلات، بينما يتمتع الآخر بعقل لامع وذكاء خارق يمكنه حل أصعب المشكلات في دقائق معدودة.", "/images/products/9789778200287.webp", "9789778200287", "عقل بلا جسد", 224, 170m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 145, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتناول كل المقالات هنا الظواهر الأسطورية والأساطير، وهي بمثابة موسوعة للتعابير المخيفة في الأفلام والكتب وغيرها من أعمال الرعب، إلى جانب أبرز الكتاب والممثلين والمخرجين العاملين في هذا المجال.\nكما تُسلّط الضوء على بعض أشهر شخصيات الرعب مثل دراكولا وفرانكشتاين والذئاب المتحولة والزومبي، وأسماء الشياطين مثل بابوميت، ولوسيفر، وأبراكساس، بالإضافة إلى الأساليب السحرية المتعددة وأشهر السحرة، وحتى القتلة المتسلسلين الذين ارتكبوا مذابح مروعة.", "/images/products/9789778200225.webp", "9789778200225", "موسوعة الظلام", 191, 150m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 146, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من المقالات التي تقوم بتفكيك الأساطير غير المنطقية المنتشرة حول العالم، خاصةً في العالم الغربي مثل مثلث برمودا، والأطباق الطائرة، والعلاج الروحي، ولعنة الفراعنة، وغيرها من الأساطير الشهيرة.\nيفترض الكاتب أن شعبية هذه الأساطير تعود إلى دوافع نفسية لدى البشر، ورغبة أدمغتهم في الإيمان بالأوهام، وقدرة بعض الأشخاص على زرع هذه المعتقدات.", "/images/products/9789778200249.webp", "9789778200249", "هادم الاساطير", 164, 130m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 147, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قصص رعب قصيرة تتناول كل ما هو غير طبيعي: من الأشباح والشياطين الناطقة والأحلام الغريبة إلى الجنون والسفر عبر الزمن، مع لمسة من الرومانسية وعلم النفس.", "/images/products/9789778200607.webp", "9789778200607", "لست وحدك", 234, 170m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
