                    { 149, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من المقالات التي تتناول الظواهر الخارقة والغرائبية، القريبة من الأساطير، والظواهر العلمية ذات طابع الخيال العلمي؛ أشياء تقع على حافة الواقع والخيال.", "/images/products/9789778200324.webp", "9789778200324", "الحافة", 208, 170m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 150, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قصص رعب قصيرة كتبها أحمد خالد توفيق بأسلوبه الساخر المميز، والتي تدفع القارئ إلى النهاية وهو يفكر: \"آه، الآن فهمت!\" بطريقة غير متوقعة.", "/images/products/9789778200263.webp", "9789778200263", "الأن أفهم", 148, 130m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 151, "أحمد خالد توفيق", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة قصص قصيرة مليئة بالأفكار؛ بعضها يتضمن أفكارًا فلسفية مبسطة، والبعض الآخر يتسم بالسخرية من كل شيء، حتى من الأفكار نفسها.", "/images/products/9789778200157.webp", "9789778200157", "قصاصات قابلة للحرق", 112, 120m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 152, "أحمد خالد توفيق", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الشخصية الرئيسية \"هند\" تتمتع بقدرات خارجة عن الحواس (ESP)، ويساعدها محمود الألفي على استغلال هديتها بشكل إيجابي.\nوفي كل مرة يطلب فيها ضابط الشرطة \"سمير الوانا\" مساعدتها، تساهم هند في حل العديد من الجرائم.", "/images/products/9789778200256.webp", "9789778200256", "ESP", 216, 170m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 153, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من المقالات التي تتناول موضوعات سياسية ومختلف الأحداث الحياتية.", "/images/products/9789778200638.webp", "9789778200638", "لا مكان للملل", 184, 150m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 154, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"سبعة ألوان قوس قزح... سبع قصص رعب\"\nكتبها اثنان من أشهر كتّاب الرعب في مصر والعالم العربي.", "/images/products/9789778200614.webp", "9789778200614", "قوس قزح", 140, 130m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 155, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من المقالات الساخرة التي تتناول مواقف الحياة اليومية؛ ففي بعض الأحيان تحدث أشياء لا ندرك مدى تأثيرها الحقيقي، والهدف منها رسم الابتسامة، وإثارة الضحك، وتحفيز السعادة.", "/images/products/9789778200621.webp", "9789778200621", "ضحكات كئيبة", 250, 170m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 156, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من المقالات التي تجمع بين الفرح والأفكار التي قد تجعلك تتوقف أحيانًا للتفكير في شؤون الحياة؛ كتب بعضها قبل الثورة المصرية والبعض الآخر بعدها.", "/images/products/9789778200201.webp", "9789778200201", "شاي بالنعناع", 164, 140m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 157, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من المقالات التي تتناول آراء في السياسة، والفن، والأدب، والأفلام، والشؤون الخاصة.", "/images/products/9789778200195.webp", "9789778200195", "الغث من القول", 226, 170m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 158, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من المقالات الساخرة التي تتناول هلوسات الناس، وهلوسات الكتابة، والسينما، والمرور، والتعليم، والهلاوس الطبية والغذائية.", "/images/products/9789778200348.webp", "9789778200348", "وساوس وهلاوس", 232, 170m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 159, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتاب يأخذنا في رحلة شيقة عبر عالم السينما، حيث يناقش 33 فيلمًا مع مقاطع قصيرة عنها، مما يمنح القارئ تجربة فريدة ومميزة.", "/images/products/9789778200171.webp", "9789778200171", "افلام الحافظة الزرقاء", 270, 185m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 160, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة أخرى من المقالات الساخرة عن مواقف الحياة اليومية، التي تحدث أحيانًا أشياء لا ندرك عمق تأثيرها، بهدف رسم الابتسامة، وإثارة الضحك، وتحفيز السعادة.", "/images/products/9789778200232.webp", "9789778200232", "زغازيغ", 170, 150m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 161, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من المقالات المتنوعة التي تتميز بخفة الظل والفكاهة، وتتناول العديد من الموضوعات التي تُضحك القارئ.", "/images/products/9789778200331.webp", "9789778200331", "فقاقيع", 220, 170m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 162, "أحمد خالد توفيق", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من خمسة روايات مترابطة تتحدث عن كيان يعيش كفيروس حاسوبي، يتجول بين أجهزة الكمبيوتر في جميع أنحاء العالم، يكتشف الأسرار ويشهد أشياء مرعبة، مما يجعلك تغوص في عالم مختلف تمامًا.", "/images/products/9789778200188.webp", "9789778200188", "WWW", 422, 240m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 163, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في زمنٍ ينهار فيه كل شيء، وتقترب البشرية من حافّة الفناء، تبدأ الحكايات الأخيرة في التكوّن.\nحكايات عن مدنٍ سقطت، وأحلامٍ تحوّلت إلى كوابيس، وأسرارٍ تُروى قبل أن يختفي آخر من يتذكرها.\nفي \"يوميات آخر البشر\"، يصحبنا د. نبيل فاروق في رحلة بين عوالم من الخيال العلمي والرعب والغموض، حيث لا يكون الإنسان دائمًا البطل… وأحيانًا لا يكون حتى الناجي الأخير.\nفهل ستكشف هذه اليوميات عن الأمل… أم عن النهاية التي لا مفرّ منها؟", "/images/products/9789778202816.webp", "9789778202816", "يوميات اّخر البشر", 124, 170m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 164, "خولة حمدي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث القصة حول ريما، الفتاة المسلمة من تونس التي فقدت والديها. كانت آخر كلمات والدتها إلى جارتها اليهودية يعقوب أن يربيها على نهج الإسلام. كبرت الفتاة، وأخذت ترتدي الحجاب، فبدأت تعتبر يعقوب غريبًا عنها. حينها، طالبت زوجته تانيا أن يختار بينها وبين ريما التي أحبها كابنته. فقام بإرسالها إلى أخته راشيل في لبنان، لتتعقد الأمور عندما اضطرت إلى التنقل بسبب سوء معاملة زوج راشيل لها. وعاشت بعدها مع صديقة راشيل، سونيا، التي كانت من سكان تونس أيضًا لكنها فرت من زوجها التعسفي برفقة ابنتيها ندى ودانا إلى مدينة قانا في لبنان. وهكذا، تتشابك مصائر الجميع في دوامة من التعقيد.\nقصة عن الإنسانية، والأديان، والحب.", "/images/products/9789776376441.webp", "9789776376441", "في قلبي أنثى عبرية", 388, 325m, new DateTime(2013, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 165, "خولة حمدي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذا الجزء الأخير، يبرز عمر وياسمين كشخصيات مركزية، حيث ينقل الكاتب مشاعرهما بعبقرية تجعل القارئ يشعر وكأنه يعيش كل لحظة من خلال قلبيهما.\nتتعمق الرواية في تناول قضايا اجتماعية وإنسانية متعددة، مؤكدةً على أهمية الأفراد المبادرين في المجتمع؛ فحتى أرقى الأعمال يمكنها أن تترك أثرًا دائمًا، مما يبرز القوة الهادئة للجهود الخيرية.\nكما تطرق القصة إلى أزمة اللاجئين السوريين والحرب الأهلية، لتأخذ القارئ في رحلة عبر الأردن، خاصةً مخيم الزعتري، إلى جانب تونس، والمغرب، وباريس، وجبال سويسرا الساحرة.\nبأسلوب جذاب ومشوق، تنسج هذه الثلاثية تسلسلاً قويًا من الأحداث، فتشد القارئ بسرد مميز يحافظ على انتباهه من البداية حتى النهاية.", "/images/products/9789778201338.webp", "9789778201338", "ياسمين أبيض", 560, 400m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 166, "خولة حمدي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مفتاح العودة.\nلم تكن قصة المفاتيح مجرد أسطورة، بل كانت حقيقية.\nنحتفظ بالمفتاح والصور القديمة، ونعهد أن نرعى تلك الحكايات. نسقي الذكريات بالدموع والحنين حتى لا ننسى من نحن وما هي قضيتنا.", "/images/products/9789778200935.webp", "9789778200935", "ياسمين العودة", 544, 370m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 167, "خولة حمدي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتناول هذه الرواية وضعًا حساسًا للغاية، حياة اللاجئين العرب والمسلمين في فرنسا، ومدى صعوبة الاندماج في مجتمع متنوع العادات والمعتقدات والأديان.\nتحكي عن ياسمين، الفتاة المسلمة التي ترتدي الحجاب، والمشكلات التي تواجهها بسببه، وبالمقابل عن عمر المغربي، الشاب العالم الذي يبحث في الاندماج النووي البارد لإيجاد مصدر طاقة نظيف، إلا أن الأمور تنقلب عندما يحدث انفجار، فيجد نفسه متهمًا بالإرهاب ومهددًا بالسجن.\nكما نسلط الضوء على رنيم، الفتاة المصرية الليبرالية التي عاشت حياتها مندمجة في مجتمعها، مدافعة عن عمر وموقنة بأنه ليس إرهابيًا.", "/images/products/9789776376632.webp", "9789776376632", "غربة الياسمين", 408, 275m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 168, "خولة حمدي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وصل نادر الشاوي، المهاجر غير الشرعي، إلى الأراضي الفرنسية في عام 2004 على متن إحدى \"قوارب الموت\" القادمة من الجزائر. وفي عام 2035، ترشح ابنه خليل، الشاب المحامي، للانضمام إلى مجلس الشيوخ الفرنسي، حيث يكتشف تاريخي والده عندما يتلقى بعض الرسائل مصحوبة بغطاء رصاصة.\nتسلط الرواية الضوء على معاناة اللاجئين العرب في أوروبا، لا سيما في فرنسا، مع تسليط الضوء على أزمة الهوية المزدوجة بين الاندماج والتمسك بالجذور.\nكما تتناول الإرهاب، بدءًا من \"العشرية السوداء\" في الجزائر وصولاً إلى هجمات باريس عام 2015، وتكشف عن الوجه المروع لتجربة الهجرة غير الشرعية والتمييز العنصري الذي يواجهه المهاجرون في أوروبا، والذي بعيد كل البعد عن صورة \"الجنة الأرضية\" التي كانوا يحلمون بها.", "/images/products/9789776376908.webp", "9789776376908", "أن تبقى", 384, 275m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 169, "خولة حمدي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تعود الرواية لتستعرض ما جرى بعد الثورة التونسية، في قصة تحكي خيبة الأمل التي أعقبت الثورات العربية غير المكتملة.\nيقول كل من التونسية ليلى، والمصرية سوسن، والسوري نزار: \"ليست ثورات، بل مجرد شائعات مترددة.\"\nتعود ليلى إلى وطنها من سويسرا لتتأمل في العلاقات المتصدعة، ووطنٍ متمرد، ويبدأ فراس، المتشبث بذكرياته الماضية، رحلة لاكتشاف وطنها الحقيقي الذي كانت تعرفه فقط من خلال حكايات والدها، تلك الحكايات التي كانت تبحر بها في بحر معاني الوطن والثورات.", "/images/products/9789778200492.webp", "9789778200492", "أين المفر", 432, 300m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 170, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تفقد (ليك) والدها فجأة، فتجد نفسها مضطرة لترك حياتها في تكساس، والانتقال مع والدتها وأخيها الصغير (كيل) إلى مدينة جديدة.\nهناك تلتقي بجارها الجديد (ويل كوبر)، شاب يشاركها شغفها بالموسيقى، فينشأ بينهما انجذاب قوي يبدو وكأنه بداية لقصة حب جميلة.\nلكن سرعان ما يتغير كل شيء، حين تكتشف أن (ويل) هو مدرّسها الجديد في الثانوية، فيتحول الانجذاب البريء إلى موقف معقد، يضعهما في مواجهة تحديات صعبة تتعلق بالمجتمع والقيم.\nفهل يستحق حبهما المخاطرة؟ أم أن بعض الخطوط وُضعت لتظل غير قابلة للتجاوز؟", "/images/products/9789778201666.webp", "9789778201666", "صدمات", 336, 375m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 171, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "‎الآن حان وقت سماع القصة من الجانب الآخر، من منظور (ويل).\n‎مع بداية زواجه من (ليك)، يبدأ في سرد حكايته، كاشفًا عن مشاعره منذ اللحظة الأولى التي وقعت عيناه عليها، وحتى وصولهما إلى هذه المرحلة من حياتهما.\n‎من خلال كلماته نكتشف صراعاته الداخلية، وألمه لفقد والديه، ومسؤوليته تجاه شقيقه الأصغر، وكذلك مخاوفه من خسارة (ليك) في كل مرة حاول فيها كبح مشاعره.\n‎هذه الرواية ليست إعادة للأحداث، بل نافذة تكشف لنا الجانب الخفي من القصة التي عرفناها من قبل.", "/images/products/9789778202878.webp", "9789778202878", "هذه الفتاة", 378, 410m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 172, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكاتبة الحائزة على لقب نيويورك تايمز الأفضل مبيعًا، والتي أبهرت القرّاء بروايتها ميؤوس منه، قصة ما\nحدث عندما التقت الفتاة المضطربة سكاي مع صديق طفولتها الذي فقدته منذ زمن طويل، دين هولدر.\nبمساعدة دين هولدر، كشفت سكاي عن أسرار عائلية صادمة وتصالحت مع ذكريات وعواطف خلّفت\nجروحًا عميقة.\nميئوس منه كانت قصة سكاي. والآن، في رواية فقدان الأمل، نتعرف أخيرًا على حقيقة &quot;دين هولدر&quot;.\nيعيش هولدر حياة مظلمة بسبب الطفلة الصغيرة التي لم يتمكن من إنقاذها من الخطر الوشيك، وتغمره\nمشاعر الذنب والندم. لم يتوقف هولدر عن البحث عنها، يعتقد أن العثور عليها سيجلب له السلام الذي\nيحتاجه للتقدّم في الحياة. ومع ذلك، لم يكن هولدر يتوقع أن يواجه المزيد من الألم في لحظة لقائهما مجددًا.\nفي رواية فقدان الأمل يكشف هولدر طريقة تأثير أحداث طفولة &quot;سكاي&quot; عليه وعلى عائلته، مما دفعه إلى\nالبحث عن الفداء من خلال إنقاذها. ولكنه فقط حب سكاي الذي يمكنه من البدء في شفاء نفسه.", "/images/products/9789778202229.webp", "9789778202229", "بدون ميريت", 420, 440m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 173, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكاتبة الحائزة على لقب نيويورك تايمز الأفضل مبيعًا، والتي أبهرت القرّاء بروايتها ميؤوس منه، قصة ما\nحدث عندما التقت الفتاة المضطربة سكاي مع صديق طفولتها الذي فقدته منذ زمن طويل، دين هولدر.\nبمساعدة دين هولدر، كشفت سكاي عن أسرار عائلية صادمة وتصالحت مع ذكريات وعواطف خلّفت\nجروحًا عميقة.\nميئوس منه كانت قصة سكاي. والآن، في رواية فقدان الأمل، نتعرف أخيرًا على حقيقة &quot;دين هولدر&quot;.\nيعيش هولدر حياة مظلمة بسبب الطفلة الصغيرة التي لم يتمكن من إنقاذها من الخطر الوشيك، وتغمره\nمشاعر الذنب والندم. لم يتوقف هولدر عن البحث عنها، يعتقد أن العثور عليها سيجلب له السلام الذي\nيحتاجه للتقدّم في الحياة. ومع ذلك، لم يكن هولدر يتوقع أن يواجه المزيد من الألم في لحظة لقائهما مجددًا.\nفي رواية فقدان الأمل يكشف هولدر طريقة تأثير أحداث طفولة &quot;سكاي&quot; عليه وعلى عائلته، مما دفعه إلى\nالبحث عن الفداء من خلال إنقاذها. ولكنه فقط حب سكاي الذي يمكنه من البدء في شفاء نفسه.", "/images/products/9789778201642.webp", "9789778201642", "فقد", 440, 450m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 174, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قصة حب لا تُنسى، تكسر كل القواعد، من كولين هوفر، المؤلفة رقم 1 في قائمة الأكثر مبيعًا\n\nلصحيفة نيويورك تايمز.\n\nلم تقع تايت كولينز في الحب من أول نظرة عندما التقت بالمعذَّب سرًّا مايلز أرتشر؛ بل لا\nيمكن عدُّهما في الأصل أصدقاء. الشيء الوحيد المشترك بينهما كان الانجذاب الجسدي الذي\nلا يُمكن إنكاره. فما إن كشفت رغباتهما عن نفسها، حتى أدركا أنهما توصلا لاتفاقٍ مثالي بلا\nأية قيود. فهو لا يبحث عن الحب، وهي لا تملك الوقت لذلك، ومن هنا لا يتبقى لهما سوى\nالعلاقة الجسدية، التي قد تكون مُرضية بشكلٍ مدهش، إذا التزمت تايت بقاعدتين وضعهما\nمايلز: لا أسئلة أبدًا عن الماضي، ولا توقع لأي مستقبل قد يجمعهما على الإطلاق.\nلقد ظنَّا أن بإمكانهما الالتزام بالاتفاق، لكن كل شيء في المعادلة يتغيَّر، ما إن تظهر المشاعر\nالحقيقية على السطح.\n                                                  فالقلوب تُخترَق.\n                                                   والوعود تُكسَر.\n                                                 والقواعد تتحطم.\n                                                والحب يُصبح بشعًا.\n  \n*وحدها كولين هوفر التي تستطيع وضع هذا القدر من التألق في رواية واحدة. - جيمي\nماجواير، المؤلفة الأكثر مبيعًا في قائمة صحيفة نيويورك تايمز، ومؤلفة رواية &quot;كارثة\nجميلة&quot;.", "/images/products/9789778202717.webp", "9789778202717", "حب قبيح", 440, 450m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 175, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أحيانًا، قد يترك اكتشاف الحقيقة في داخلك حالة من اليأس أعمق مما يتركه الإيمان بالأكاذيب...\n\nهذا ما تدركه سكاي، الفتاة ذات السابعة عشرة من عمرها، بعد لقائها مع دين هولدر. شاب يتمتع بسمعة تضاهي سمعتها، وبقدرة غير عادية على استحضار مشاعر لم تختبرها من قبل؛ فهو يخيفها ويسحرها في لقاء واحد فقط، بينما يوقظ بها شعورًا عميقًا يحرّض ذكريات مدفونة من ماضٍ كانت تفضل أن يبقى خفيًا.\n\nتكافح سكاي للحفاظ على مسافة منه، مع علمها بأنه لا يجلب سوى المشاكل، لكن هولدر يُصر على معرفة كل شيء عنها. وبعد أن تستسلم أخيرًا لمطاردته الدؤوبة، تكتشف أن هولدر ليس كما كان يدعي. وعندما تنكشف الأسرار التي كان يخفيها، سيتغير كل جانب من جوانب حياة سكاي إلى الأبد.", "/images/products/9789778201345.webp", "9789778201345", "ميؤوس منه", 432, 400m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 176, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا تودُّ مورغان جرانت وابنتها كلارا، البالغة من العمر ستة عشر عامًا، أن يكونا متشابكين بأي شكل من الأشكال.\n\nمورغان مصممة على منع ابنتها من تكرار الأخطاء التي ارتكبتها هي بنفسها؛ ففي شبابها، من خلال حملها والزواج في وقت مبكر جدًا، أجلت تحقيق أحلامها. بينما ترفض كلارا أن تسلك درب والدتها المتوقعة، التي تخلو من أي عفوية.\n\nومع تضارب الشخصيات وتعارض الأهداف، تجد مورغان وكلارا صعوبة متزايدة في التعايش. الشخص الوحيد الذي يستطيع أن يجلب السلام إلى البيت هو كريس—زوج مورغان، ووالد كلارا، والعمود الفقري للعائلة. لكن هذا السلام ينكسر حين يتورط كريس في حادث مأساوي ومثير للشكوك، حيث تمتد عواقبه القاسية وطويلة الأمد إلى ما هو أبعد من مجرد مورغان وكلارا وحدهما.\n\nوأثناء سعيهما لإعادة بناء كل ما تحطم حولهما، تجد مورغان العزاء في آخر شخص كانت تتوقعه، بينما تلجأ كلارا إلى الصبي الذي حُرِمت من رؤيته. ومع مرور الأيام، تتكشف أسرار جديدة، ويتفاقم الاستياء وسوء الفهم، مما يجعل العلاقة بين الأم وابنتها تتباعد أكثر فأكثر، حتى يصبح التقارب بينهما شبه مستحيل.", "/images/products/9789778201369.webp", "9789778201369", "نادمة عليك", 448, 400m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 177, "براندون ساندرسون", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قد هُزِم الشر...\nلكن الحرب لم تبدأ إلا الآن.\nلقد صنعوا المستحيل؛ أطاحوا بالطاغية الذي استمرَّ حكمه الغاشم ألف عام. والآن، بات لزامًا على \"ڤين\"، فتاة الشوارع التي غدت أقوى \"وليدة ضباب\" في البلاد، و\"إليند ڤينتشر\"، الشاب المثالي النبيل الذي يهواها، أن يُشيَّدا مُجتمعًا جديدًا سليمًا على أنقاض إمبراطوريةٍ مُتداعية.\nلكنهما ما كادا يشرعان في مهمتهما، حتى هاجمتهما ثلاثةُ جيوشٍ مُنفصِلة. وبينما يشتدُّ عليهم الحصار، تلوح في الأفق أسطورةٌ قديمةٌ لتبعث بصيصًا من الأمل. ولكن، حتى لو كانت تلك الأسطورة حقيقيةً، فلا أحد يعلم أين يُوجَد بئر العروج ذاك، أو أيّ قوةٍ تلك التي يمنحها.\n\nلرُبَّما كان قتل \"اللورد الحاكم\" هو الجزء الأسهل، فالنجاة من عواقب سقوطه هي التحدّي الحقيقي.", "/images/products/9789778203042.webp", "9789778203042", "بئر العروج", 1132, 975m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 178, "براندون ساندرسون", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ستيفن ليدز عبقري يتمتع بموهبة لا نظير لها، إذ أنه يستطيع تعلم أي مهارة جديدة أو مهنة أو فن جديد في غضون ساعات فحسب. لكن كي يتمكن عقله من احتواء كل ذلك، فهو يلجأ إلى خلق هلاوس في صورة أشخاص متخيلين، يسميهم ستيفن «جوانبه» المختلفة، للاحتفاظ بكل تلك المعلومات وإظهارها وقت اللزوم. وأينما ذهب ستيفن، يتبعه حشد من الخبراء الخياليين، كي يسدوا إليه النصح والمشورة، ويقدموا له التفسير والشرح الذي يحتاجه منهم. وهو يستعين بفريقه هذا في حل القضايا المختلفة، نظير الحصول على أجر.\n\nاسمي ستيفن ليدز، وأنا عاقل تمامًا. لكنَّ هلاوسي كلها في غاية الجنون...\nأنا لست ما يتوقعه الناس أبدًا. يتخيلني البعض كما لو كنت عالِمًا غريب الأطوار من نوع ما، بينما يتخيلني البعض الآخر كنجم من نجوم افلام الحركة. لكن ما يجدونه بدلًا من ذلك هو رجل هادئ إلى حدٍّ ما في الثلاثينيات من عمره، طبيعي تمامًا. أحيانًا ما أشعر وكأنني أُشبِهُ غرفتي البيضاء، بطريقةٍ ما. سجل فارغ تمامًا. تنفرد جوانبي المختلفة بكل الخصائص المميزة، بينما أحاول أنا جاهدًا ألا أكون بارزًا للعيان. لأنني لست مجنونًا...\nلديَّ جوانب متعددة. سبعة وأربعون، على وجه الدقة... لا أحتاجهم جميعًا في الغالب، وفي الواقع فإن تخيُّل أكثر من  أربعة أو خمسة في نفس الوقت أمر مرهق، ولا يمكنني القيام به لفترة طويلة... في بعض الأحيان، تأتي مهمة تتطلَّب جهدًا إضافيًّا، وأحتاج إلى أن يصغي إلىَّ عدد أكبر من جوانبي. لهذا السبب أنشأتُ الغرفة البيضاء. كانت جدرانها خالية، ومطلية هي والأرض والسقف بنفس اللون الأبيض غير اللامع، وجميع أسطح الغرفة ناعمة وباردة ولا يقطعها شيء سوى الأنوار في السقف. كانت عازلة للصوت وهادئة، ولا يوجد بها ما يشتت الانتباه، ولا شيء أركز عليه سوى عشرات الأشخاص الوهميين الذين تدفقوا عبر الباب المزدوج...\nكانت القائمة تطول. انضموا إليَّ على مهل، في مهمةٍ تلو الأخرى، حينما كنت أحتاج إلى تعلُّم مهارة جديدة، لأحشو عقلي المكتظ بالفعل بمجموعة متنوعة من الكفاءات المتزايدة. تصرفوا مثل الأشخاص الحقيقيين تمامًا، وهم يتحدثون بعدة لغات...\nوعلى الرغم من أن كثيرًا من جوانبي كانوا يتحدثون عن حياتهم، وأسرهم، وأصدقائهم، وهواياتهم، إلا أنني لم أرَ في الواقع أي شيءٍ من هذا. وكان ذلك من الجيد، لأن تتبُّع سبعٍ وأربعين هلوسة أمر شاق بما فيه الكفاية. لو كان عليَّ تخيُّل أقاربهم أيضًا، فقد ينتهي بي الحال إلى الجنون...\nأجل، كلُّ هذا داخل عقلي فحسب، لكن الألم «كلُّه داخل عقلي» أيضًا، والحُب «كلُّه داخل عقلي». كل الأشياء المُهمَّة في الحياة هي تلك التي لا يمكنك قياسها! الأشياء التي تختلِقُها أدمغتنا! كونُها مُختلَقةً لا يعني أنها غير ذات أهمية.", "/images/products/9789778201727.webp", "9789778201727", "الفيلق", 536, 490m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 179, "طاهرة ماڤي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أنا محملة بلعنة، وأحمل هبةً في آنٍ واحد.\nأنا وحشٌ، ولكني أكثر من مجرد بشر.\nلمستي قاتلة، ولمستي تجسّد القوة.\nأنا سلاحهم، وسأنتقم.\n\nلم يمسّ جوليت أحدًا منذ 264 يومًا بالضبط.\nآخر مرة لمست فيها أحدًا كانت مجرد حادثة، لكن \"إعادة التأسيس\" سجنتها بتهمة القتل. لا أحد يعرف سبب فتك لمسة جوليت؛ وطالما أنها لا تؤذي أحدًا آخر، لا يُعيرها أحد اهتمامًا، فالعالم منشغل بانهيار ذاته إلى شظايا، والأمر لا يشغل بال أحد بفتاة تبلغ من العمر سبعة عشر عامًا.\nتفتك الأمراض بالسكان، ويصبح العثور على الطعام أمرًا نادرًا، والطيور لم تعد تحلّق، والغيوم باتت بلون خاطئ.\nأعلنت \"إعادة التأسيس\" أن طريقتها هي السبيل الوحيد لإصلاح الأمور، فأسَرعوا برمي جوليت في زنزانة. والآن، بعد أن زادت أعداد القتلى حتى بدأ الناجون يهمسون بالحرب، تغيرت وجهات نظرهم؛ فقد تكون جوليت أكثر من مجرد روح معذبة محشوة في جسد سام، وربما هي بالضبط ما يحتاجونه الآن.\nوعليه أن تختار: أن تكون سلاحًا، أو أن تكون محاربة.", "/images/products/9789778201109.webp", "9789778201109", "حطمني", 336, 300m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 180, "طاهرة ماڤي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في الجزء الثاني  من سلسلة \"حطمني\" للمؤلفة الأكثر مبيعًا وفق نيويورك تايمز، طاهره مافي، كان من المفترض أن تكفي لمسة واحدة من جوليت لقتل وارنر، لكن مناعته الغامضة ضد قوتها القاتلة هزّتها وتركتها تتساءل لماذا فشل درعها الأخير أمام الشخص الذي تحتاج إلى حمايته بشدة.\nنجحت هي وآدم في الفرار من مكائد وارنر والانضمام إلى مجموعة من المتمردين، كثيرٌ منهم يمتلك قدرات خارقة. ستتمكن جوليت أخيرًا من محاربة \"إعادة التأسيس\" بنشاط ومحاولة إصلاح عالمها الممزق، وربما يساعدها هؤلاء الحلفاء الجدد في كشف سر مناعة آدم ووارنر ضد بشرتها القاتلة.\nعالم جوليت مليء بالإثارة عالية المخاطر والرومانسية المشوقة، ما يجعله مثاليًا لعشاق سلسلة \"الملكة الحمراء\" لفيكتوريا أفيارد وثلاثية \"أكثر العقول ظلاماً\" لألكسندرا براكن.\nوقد أشاد رانسوم ريجز، المؤلف رقم 1 بحسب نيويورك تايمز، في قوله: \"ملحمة مثيرة ومليئة بالمخاطر لاكتشاف الذات والحب الممنوع؛ سلسلة 'حطمني' قراءة لا بد منها لعشاق أدب الشباب الديستوبي—أو أي أدب!\"", "/images/products/9789778201536.webp", "9789778201536", "فسرني", 464, 415m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 181, "طاهرة ماڤي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في الجزء الثالث من سلسلة \"حطمني\" الأكثر مبيعًا، والذي وصفه رانسوم ريجز بأنه \"ملحمة مثيرة ومليئة بالمخاطر لاكتشاف الذات والحب الممنوع\"، تجد جوليت نفسها بعد تدمير \"نقطة أوميغا\" غير مدركة لما إذا كان المتمردون أو أصدقاؤها، أو حتى آدم، لا يزالون على قيد الحياة.\nومع ذلك، لن يمنعها ذلك من السعي للقضاء على \"إعادة التأسيس\" مرة وإلى الأبد. الآن، عليها أن تعتمد على وارنر، القائد الوسيم للقطاع 45، الشخص الذي لم تعتقد يومًا أنها تستطيع الوثوق به، والذي أنقذ حياتها يومًا ما. يعد وارنر بمساعدة جوليت على التحكم في قواها وإنقاذ عالمهم المحتضر، لكن رغباته لا تقتصر على ذلك وحده.", "/images/products/9789778201611.webp", "9789778201611", "أشعلني", 420, 385m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 182, "طاهرة ماڤي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كانت جوليت فيرارز تظن أنها انتصرت؛ فقد استولت على القطاع 45 وتُعيّنت كالقائدة العليا الجديدة، وأصبح وارنر إلى جانبها. لكنها لا تزال الفتاة التي تملك القدرة على القتل بلمسة واحدة، والآن أصبح العالم بأسره بين يديها.\nفحين تضرب المأساة، من ستكون؟ وهل ستستطيع السيطرة على القوة التي تملكها وتحويلها إلى قوة للخير؟", "/images/products/9789778202304.webp", "9789778202304", "أعدني", 424, 400m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 183, "طاهرة ماڤي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه الفتاة لم تكن لك يومًا، هذه الفتاة حُكم عليها بالموت في اللحظة التي أطلقت عليها اسم \"جولييت\".\n\nظنت جولييت فيرارز أنها قادرة على هزيمة \"إعادة التأسيس\"، أنها قادرة أخيرًا على السيطرة على حياتها وقوتها وألمها، ولكن فجأة ينهار كل شيء لتكتشف أن حياتها مجرد حفنة من الأكاذيب، ولكي تظل على قيد الحياة.. لكي تنتصر؛ عليها أن تتذكر ماضيها.", "/images/products/9789778202540.webp", "9789778202540", "أعصني", 334, 350m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 184, "جويندا بوند", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مختبر غامض. عالم شرير. تاريخي سري. إذا كنت تعتقد أنك تعرف الحقيقة وراء والدة إلفن، فاستعد لأن تنقلب مفاهيمك رأسًا على عقب في هذه المقدمة المثيرة للمسلسل الشهير \"أشياء غريبة\".\nفي صيف عام 1969، يتردد صدى الصراع بين شباب أمريكا في كل من الداخل والخارج. كطالبة في حرم جامعي هادئ بعمق ولاية إنديانا، كانت تيري إيفز بعيدة كل البعد عن الخطوط الأمامية لحرب فيتنام أو الاحتجاجات المشتعلة في واشنطن.\nلكن العالم يتغير، ولم تكتفِ تيري بالمشاهدة من على الهامش. حينما بدأ الخبر بالانتشار عن تجربة حكومية مهمة في بلدة هوكينز الصغيرة، انضمت تيري كموضوع تجريبي للمشروع الذي حمل الاسم الرمزي MKUltra. شاحنات غير موسومة، مختبر بعيد في أعماق الغابات، مواد تغير الوعي تُعطى من باحثين متكتمين، وغموض تصر تيري الشابة الثائرة على كشفه.\nوراء جدران مختبر هوكينز الوطني، وتحت نظرة مديره الثاقبة، الدكتور مارتن برينر، تكمن مؤامرة أعظم مما تخيلت. لمواجهتها، ستحتاج تيري إلى مساعدة زملائها في التجربة، بمن فيهم شخص غامض لدرجة أن العالم لا يعرف بوجوده—فتاة شابة تمتلك قوى خارقة لا تُفسر، وتحمل رقمًا بدلاً من اسم: 008.\nوسط تصاعد التوترات في العقد الجديد، بدأ تيري والدكتور برينر حربًا مختلفة، حربًا تصبح فيها العقل البشري ساحة المعركة.", "/images/products/9789778200997.webp", "9789778200997", "عقول مرتابة", 392, 370m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 185, "آدم كريستوفر", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يكشف الرئيس جيم هوبر عن الأسرار التي طال انتظارها لإلفن حول حياته السابقة كمحقق شرطي في مدينة نيويورك، مواجهًا ماضيه قبل أحداث المسلسل الشهير \"أشياء غريبة\".\nفي كريسماس هوكينز عام 1984، كان كل ما يرغب به هوبر هو قضاء عيد ميلاد هادئ مع إلفن، لكن ابنته المتبناة كانت لها خططها الخاصة. رغم اعتراضات هوبر، خرجت من القبو صندوق كرتوني مكتوب عليه \"نيويورك\"، وبدأت الأسئلة الصعبة تتطاير: لماذا غادر هوبر هوكينز منذ كل تلك السنين؟ ماذا تعني كلمة \"فيتنام\"؟ ولماذا ظل صامتًا عن نيويورك؟\nعلى الرغم من أنه يفضل مواجهة جحافل المخلوقات الغريبة على الحديث عن ماضيه، يعلم هوبر أنه لم يعد بإمكانه إنكار الحقيقة. وهكذا تبدأ قصة الحادثة في نيويورك—آخر قضية كبيرة قبل أن يتغير كل شيء.\nفي صيف نيويورك عام 1977، يبدأ هوبر حياةً جديدة بعد عودته من فيتنام؛ فوجود فتاة صغيرة، وزوجة محبة، ودور جديد في شرطة نيويورك يسهل عليه العودة للحياة المدنية. لكن مع ظهور عملاء اتحاديين غامضين واستيلائهم على ملفات سلسلة جرائم وحشية غير محلولة، يتولى هوبر زمام الأمور مخاطراً بكل شيء لاكتشاف الحقيقة.\nوسرعان ما يتسلل هوبر إلى صفوف عصابات شوارع نيويورك الشهيرة، لكن حين يوشك على حل القضية، يحل الظلام فجأة على المدينة، فيغرق هوبر في عتمة لم يشهد مثلها من قبل.", "/images/products/9789778201093.webp", "9789778201093", "الظلام عند أطراف المدينة", 384, 370m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 186, "ديڤيد ستيوارت ديڤيز", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يحضر شيرلوك هولمز جلسة روحانية لكشف المحتال المتنكر في هيئة وسيط، سيباستيان ميلموث، الرجل المهووس بالسعي وراء الخلود بعد اكتشاف بردية مصرية قديمة. وتقع مهمة إيقافه ومنع الكارثة على عاتق هولمز وواتسون.\nفي هذه المغامرة السريعة، تنتقل الأحداث من لندن إلى منطقة البحيرات الخلابة، حيث يخوض هولمز وواتسون معركتهما ضد قوى الشر مرة أخرى.\nيعود الإبداع الخالد للسير آرثر كونان دويل في سلسلة جديدة من قصص التحقيق المصممة بذوق رفيع؛ بدءًا من بدايات هولمز وحتى لقاءاته المذهلة مع غزاة من المريخ، تحتضن سلسلة \"المغامرات الإضافية\" أكثر القضايا تنوعًا وإثارة لأعظم محقق في العالم.", "/images/products/9789778200911.webp", "9789778200911", "شيرلوك هولمز لفافة الموتي", 208, 200m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 187, "ديڤيد ستيوارت ديڤيز", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يصل شيرلوك هولمز الشاب إلى لندن لبدء مسيرته كمحقق خاص، فيجذب انتباه المجرم البارع، البروفيسور جيمس مورياتي. يظهر الدكتور واتسون، العائد حديثًا من أفغانستان، الذي سيصنع التاريخي قريبًا كمرافق لهولمز.\nبأسلوب يجمع بين الصدمة والإثارة، يقدم ديفيد ستيوارت ديفيز رؤيته الجريئة لأسطورة هولمز، فيصبح عمله كلاسيكية حديثة في أدب الجريمة تتحدى كل التوقعات.\nوهكذا يعود الإبداع الخالد للسير كونان دويل في سلسلة جديدة من قصص التحقيق المصممة بذوق رفيع؛ من أولى أيام هولمز وحتى لقاءاته المذهلة مع غزاة المريخ، لتحتضن سلسلة \"المغامرات الإضافية\" أكثر القضايا تنوعًا وإثارة لأعظم محقق في العالم.", "/images/products/9789778200928.webp", "9789778200928", "شيرلوك هولمز المحقق الملثم", 302, 270m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 188, "ستيوارت دوجلاس", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رواية جديدة من مؤلف أعمال هولمز الشهيرة مثل \"كنز الأبيض\" و\"المحقق المزور\".\nسُجِنَ ظلماً\nبعد استدعائه لمريض خيالي، يجد الدكتور واتسون نفسه معتقلاً بتهمة القتل المروع لسيدة مسنة. محبوسًا في سجن هولواي، ومع تكدس الأدلة ضده، يكمن أمل واتسون الوحيد في أن يكتشف شيرلوك هولمز هوية القاتل الحقيقي. ولكن عندما يظهر خطاب غامض يربطه بجرائم الابتزاز وعصابة شارع سيئة السمعة، يتوجب على هولمز أن يستخدم كل قدراته العقلية لإنقاذ صديقه من حبل المشنقة.", "/images/products/9789778201307.webp", "9789778201307", "شيرلوك هولمز سجين فوق العادة", 342, 270m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 189, "ديڤيد ستيوارت ديڤيز", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدفع زيارة رونالد تيمبل المنهارة شيرلوك هولمز والدكتور واتسون إلى الانطلاق في مطاردة طفل مخطوف.\nبدون مذكرة فدية ومع ارتباط غامض بأعلى مراتب المجتمع الفيكتوري، يتبين سريعًا أن الاختطاف ليس أمرًا عاديًا، وسرعان ما تتعرض حياة الرفاق للخطر.\nما هي الأصول الحقيقية لهذا الطفل؟ وما العلاقة التي تربطه بجرائم وايت تشابل التي وقعت قبل عقد من الزمان؟", "/images/products/9789778201222.webp", "9789778201222", "شيرلوك هولمز إرث جاك السفاح", 328, 270m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 190, "چيف ليندسي", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تعرف على ديكستر مورغان، ذئب مهذب في ثوب الحملان؛ وسيم وساحر، لكن شيئًا من ماضيه جعله يعيش وفق قواعد مختلفة. إنه قاتل متسلسل يتبع قاعدة ذهبية واحدة تجعله محبوبًا للغاية: فهو يقتل الأشخاص السيئين فقط. كما أن عمله كخبير في تحليل بقع الدم في قسم شرطة ميامي يضعه في موقع مثالي لتحديد ضحاياه.\nلكن عندما تبدأ سلسلة من جرائم القتل الوحشية التي تحمل تشابهًا مذهلًا مع أسلوبه الخاص بالظهور، يجد ديكستر نفسه بين مديح مُبالغ فيه ورعب يغمره—هل هو خائف من نفسه أم من وحش آخر؟", "/images/products/9789778201086.webp", "9789778201086", "دكستر - الحالم الغامض", 320, 300m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 191, "ڤيكتوريا أڤيارد", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا عالم مقسوم بالدم—أحمر أو فضي.\nالأحمر هم عامة الناس، يحكمهم نخبة فضية تتمتع بقوى خارقة تشبه قدرات الآلهة. ولدى \"مار بارو\"، الفتاة الحمراء البالغة من العمر سبعة عشر عامًا من منطقة \"ستيلتس\" الفقيرة، يبدو أن شيئًا لن يتغير أبدًا.\nحتى تجد نفسها تعمل في القصر الفضي. هنا، وبينما تحيط بها الأشخاص الذين تكرههم بشدة، تكتشف مار أن لديها قوة قاتلة خاصة بها، رغم دمها الأحمر، قوة تهدد بتدمير توازن السلطة.\nخوفًا من إمكانيات مار، يخفيها الفضيون في العلن، معلنين عنها أميرة فضية ضائعة منذ زمن بعيد، مخطوبة الآن لأمير فضي. ومع علمها أن أي خطأ قد يعني موتها، تعمل مار بصمت لمساعدة \"الحرس الأحمر\"، الجماعة المقاومة المتشددة، للإطاحة بالنظام الفضي.\nلكن هذا عالم من الخيانة والأكاذيب، وقد دخلت مار رقصة خطيرة—الأحمر ضد الفضيين، أمير ضد أمير، ومار ضد قلبها الخاص.", "/images/products/9789778201574.webp", "9789778201574", "الملكة الحمراء", 368, 370m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 192, "ڤيكتوريا أڤيارد", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إذا كان هناك ما تعرفه مار بارو جيدًا فهو اختلافها.\nدمها أحمر—لون العامة—لكن قدرتها الفضية، وهي القدرة على التحكم في البرق، حولتها إلى سلاح تحاول البلاط الملكي السيطرة عليه.\nيسميها العرش مستحيلةً، زائفةً، ولكن أثناء هروبها من \"مافن\"، الأمير—الصديق الذي خانها—تكشف مار شيئًا مذهلًا: إنها ليست الوحيدة من نوعها.\nمطاردة من قبل \"مافن\"، الذي تحول إلى ملك انتقامي، تنطلق مار للعثور على مجندين آخرين من المقاتلين ذوي الدم الأحمر والفضي للانضمام إلى النضال ضد ظلام مضطهديها.\nلكن مار تجد نفسها في طريق قاتل، معرضة لأن تصبح بالضبط الوحش الذي تحاول القضاء عليه.\nهل سينكسر قلبها تحت وطأة الأرواح التي يُفدى ثمنها ثمن الثورة؟ أم أن الخيانة والعداء قد قسياها إلى الأبد؟\nالجزء التالي المثير في سلسلة \"الملكة الحمراء\" يصعّد الصراع بين الجيش الثوري المتنامي والعالم المفصول بالدم، ويضع مار في مواجهة الظلام الذي نما في روحها.", "/images/products/9789778202359.webp", "9789778202359", "السيف الزجاجي", 432, 400m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 193, "أيزاك أزيموف", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كانت الإمبراطورية المجرية تحكم بسلطة لا منازع لها لمدة اثني عشر ألف سنة. والآن، هي تحتضر.\nولكن فقط هاري سلداون، مبتكر علم \"السيكوهستوري\" الثوري، يستطيع أن يرى في المستقبل—عصرًا مظلمًا من الجهل، والهمجية، والحروب ستستمر لمدة ثلاثين ألف سنة.\nلحفظ المعرفة وإنقاذ البشرية، يجمع سلداون أفضل العقول في الإمبراطورية—علماء وباحثين—ويجمعهم على كوكب قاتم على أطراف المجرة ليكونوا منارة أمل للأجيال القادمة. ويسمي ملاذه \"القاعدة\".", "/images/products/9789778201062.webp", "9789778201062", "القاعدة", 346, 300m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 194, "أيزاك أزيموف", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما تزال القاعدة تواجه الأخطار في المستقبل البعيد، فبعد تغلبها على الممالك الأربعة وفرض سيطرتها على قطاع كبير من محيط المجرة الخارجي، يظهر خطر جنرالات الإمبراطورية الساعين إلى المجد وإعادة فرض سيطرة الإمبراطورية المحتضرة. رابطة جديدة من القاعدة تسمى \"رابطة التجار الأحرار\" تسعى لوقف خطر الجنرال بِل ريوز الذي يواجه القاعدة في صراعٍ مرير قرب حافة المجرة، عند الحدود التي تتلقي فيها الحضارة الجديدة بالبربرية القديمة.\nولكن بجانب خطر الجنرالات يظهر خطر جديد، عدو لم تواجه القاعدة مثله من قبل، يبدو وكأنه قادر على تحقيق كل شيء يريده، من مجرد شخص مجهول، إلى خطر يهدد بإنهاء القاعدة، وهذا الرجل يحمل اسمًا غريبًا، البغل، وبجانب اسمه الغريب يحمل سرًا غامضًا، وقد يتوقف على كشف هذا السر مصير القاعدة، إن لم يكن مصير المجرة بأسرها.", "/images/products/9789778201284.webp", "9789778201284", "القاعدة والامبراطورية", 346, 290m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 195, "أميره بهي الدين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ست روايات في الكتاب تحكي عن أيام موحشة تهدد فيها الوطن بالفوضى وانهيار القواعد والأعراف والقوانين، فانحسرت عن أهله الحماية والطمأنينة والأمان، وأغرقهم الطوفان بمائه الأزرق السام، فلم يجدوا في حياتهم إلا أنفسهم بعجزها وضعفها، بتوحشها وخستها، فيظهر منهم مع بعضهم ومع أنفسهم أبغض وأقسى ما فيهم، لتتبدل معيشتهم إلى ما لم يتصوروه وما لم يجمح له خيالهم، وكأنهم في فيلم رعب مثلوه وأخرجوه جبرًا بلا إرادة وبلا قرار، فكانت هذه الروايات الست التي رسم الألم والدهشة أحداثها وحياة أبطالها، الألم مما يواجهون والدهشة مما يعيشون، وكأنه كابوس عجزوا عن الاستيقاظ منه والنجاة من رعبه.. روايات ست تصف أيامًا موحشة لا نتمنى أن نعيشها أبدًا ..", "/images/products/9789778598544.webp", "9789778598544", "جمهورية شارع الميتين", 342, 240m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 196, "أميره بهي الدين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الحب، العشق، الغرام، الوله.. هذا السحر والسر، السعادة والبؤس، الوهم والواقع، الكذب والحقيقة، هذا الإحساس الذي يداعب الأرواح والأفئدة والنفوس ويشاكس الخيال والوجدان، الإحساس الذي يرتقي بالمحبين لأسطع مباهج الفرحة، ويدنو بهم لأحزان البؤس الموحشة، هذا الإحساس المتفرد بكل تناقضاته، التلاقي والفراق، التنافر الاقتراب، الونس الوحشة، الفرحة التعاسة، ما الذي يصنعه الحب في حياة المحبين وكيف يرسم لهم مساراتٍ ودروبًا وكيف يسيرون فيها، وماذا تصنع لهم وفيهم وإلى أين تأخذهم أقدارهم بصحبة الحب وإلى أين تحط بهم..\nلماذا تخاويني العفاريت، كتاب يضم خمس روايات قصيرة عاش أبطالها وبطلاتها الحب بأوجهه المختلفة، وتبدلت أحوالهم وتناقضت؛ فمنهم من حلَّق حتى هوى، ومنهم من أقبل وابتعد، ومنهم من تعذب حتى تاب، ومنهم من ندم حين لا يجدي الندم.. خمس روايات قصيرة رسمت أقدار أبطالها وبطلاتها بفرشاة الحب بكل جموحه وتمرده وعطائه وغضبه، فصارت أقدارهم مثلما سنقرؤها وسارت حياتهم مثلما سنراها ونعيش منها في هذا الكتاب، لماذا تخاويني العفاريت..", "/images/products/9789778598537.webp", "9789778598537", "لماذا تخاويني العفاريت", 498, 330m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 197, "أميره بهي الدين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لاختيار؛ هذا التحدي والاختبار الشاق والصعب، هو ما جمع بين بطلات الروايات الخمس في هذا الكتاب، وكأن كلَّ ما واجهه هؤلاء النسوة من صعوبات في الحياة ومشقتها لا يكفيهن، بل ويزيد عليه في لحظات فارقة ما ستلاقيه كل منهن من ضرورة الاختيار بين صعوبات وأخرى، بين التمرد والسكون، بين الحياة والموت.. الاختيار وعذاباته ومشقته قدرهن في الحياة التي ظنن يُسرها وسهولتها، لتكشف لهن في لحظات الضعف والانكسار عن ضرورة فتح صفحات جديدة وإغلاق أخرى، السير في دروب جديدة بمشقة اكتشاف المجهول والتعامل معه وهجر الدروب المألوفة بزيف الطمأنينة الهشة ووجعها.. ما الذي صادفته \"حياة\"، وما الذي عاشته \"زهرة\"، ما الذي فُرض علي \"فتنة\"، وما الذي قهر \"مهجة\"، وكيف صنعت \"منورة\" قدرها، ولماذا سكنت \"سميحة\" لمصيرها؟! أسئلة كثيرة تلاحقنا بها الروايات الخمس وبطلاتها لنفهم وندرك كيف كان الاختيار الذي عاشته كلٌّ منهن في رحلتها صعبًا مضنيًا وكيف دفعت كل منهن ثمنه؟!\n\nإنها حكايات النساء، حكايات الحياة، وحكاياتنا جميعًا.", "/images/products/9789778598575.webp", "9789778598575", "على بوابة الليمان", 450, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 198, "أميره بهي الدين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ست روايات، وحضور فاعل طاغٍ لبطلاتهن، ما بين الحب والقهر والانتظار والأمل واليأس والتمني والخذلان.. مشاعر مختلفة متباينة، أحلام ضائعة وأمنيات.. بين كل هذا ومعه نعيش رحلة البطلات اللاتي قصصن علينا في هذا الكتاب ما عشنه وتمنينه وانتظرنه. لكل منهن عالمها المختلف وحلمها المتفرد ووجعها الحزين.. ما الذي يربط بينهن وبيننا، ما الذي يخطفنا لعوالمهن الصاخبة.. مشاعر كثيرة وأسئلة أكثر تنهمر علينا من حكاياتهن، نبتسم ونبكي ونتأمل حياتهن وحياتنا، نبحث عما يجمعنا بهن ويوحدنا معهن طوال الرحلة، إنها حكايات أصيلة ونبيلة ونشوى وصفا ومريم ولوزة.. وربما هي حكاياتنا أيضًا.", "/images/products/9789778598568.webp", "9789778598568", "لارنج ولوزة", 374, 240m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 199, "أيمن رجب طاهر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أُمر غالب، مثل كثير من العمال، بالانتقال إلى بورسعيد للعمل لدى البريطانيين، استعدادًا لمعاركهم خلال الحرب العالمية الأولى. كافح غالب لتقرير مصير ابنته الوحيدة؛ فأين سيتركها؟ ومع من؟ وفي النهاية، لم يكن أمامه خيار سوى اصطحابها معه! ولكن ذلك حدث فقط بعد أن تحولت منصورة إلى \"منصور\"، ابن غالب النجار.", "/images/products/9789778201376.webp", "9789778201376", "حيدر بن زرع النيل", 256, 180m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 200, "أيمن رجب طاهر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث هذه الحكاية في عصر المماليك، وهي قصة رومانسية عن الظلم الاجتماعي والانتقام؛ إذ تهرب شابة مع والدها على متن سفينة، وتلد ولدًا يُدعى \"أنس\". انتزع الأمير المماليك الماكر الصبي من عائلته ورباه كأمير شوارسي، دون أن يعرف أصله، في عالم جديد. هل سيرث الصبي القوة والثروة؟ أم سيثأر لعائلته ولكل المصريين المضطهدين؟", "/images/products/9789778200959.webp", "9789778200959", "أنسباي", 424, 270m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 201, "أيمن رجب طاهر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رحلة جديدة وسرد اجتماعي يأخذنا إلى عالم الهجرة غير الشرعية—مقامرة خطيرة تحمل في طياتها دمارًا يفوق الأمل. في هذه المخاطرة، يراهن المهاجر على أغلى ما يملك: حياته. هاربًا من واقع مليء بالمشاكل وفقدان الحقوق، يخوض المخاطرة على أمل الوصول إلى بر الأمان وتحقيق أحلام العمل والثروة. لكن، هل هذا هو الحل حقًا؟\nنعيش خلف الكواليس هذه الرحلة من خلال عيون طارق، الشاب من أبنوب بأسيوط، الذي رغم تخرجه من الجامعة يجد صعوبة في الحصول على عمل مناسب. وفي مواجهة الإخفاقات المتكررة، قرر الهجرة؛ فنسافر معه من الإسكندرية إلى زوارة في ليبيا عبر مراحل متعددة حتى نصل إلى المحطة قبل الأخيرة لهذه المغامرة المليئة بالمخاطر.", "/images/products/9789778200461.webp", "9789778200461", "ليل زوارة", 222, 160m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 202, "محمود علام", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"من أجلِ هذا المكان الذي نقف فيه الآن، خُضنا حروبًا، ونسجنا مؤامراتٍ، وشوهنا التاريخي والحقيقةِ ذاتها ليختفي صنيعنا، ونعود إلى الظلال التي منها نشأنا، وإليها ننتمي.. دولٌ قامت وسقطت، وملوكٌ تولوا وقُتِلوا، وبلادٌ كاملة احتُلَّت وفَنَت تطلعًا إلى السر الأعظم، وبحثًا عنه.. عن الإجابة الكبرى..\nمن أجل هذه اللحظة، وانتظارًا لها، بدأنا رحلة دامت قرونًا طويلة.. منذ فجر التاريخي، وما قبل المسيح.. منذ ما هو قبل كل شيء.. كل هذا من أجل هذه الأسطورة التي يعمل من أجلها تنظيم المصدقون الحقيقيون منذ بداية الزمان..\nأسطورة المدينة المقدسة، التي يختفي فيها مفتاح الكون، وأعظم أسرار البشر..\"\n____\nما الذي يمكن أن يحدث لو صارت للإنسان قوة الآلهة، وكيف يمكن أن يتغير العالم نتيجةً لذلك؟", "/images/products/9789778200652.webp", "9789778200652", "الجيل الثالث", 398, 250m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 203, "محمود علام", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هو كتاب علمي فلسفي ، وهو يمر من خلال صفحاته على ظواهر غامضة وألغاز علمية ومعضلات وأسرار فلسفية واجهت الجنس البشري طوال وجوده على الأرض، تتعلق كلها بالماهية الحقيقية للكون والعالم الذي نعيش فيه، وكنه الأسرار التي تختفي بعيدًا عن متناولهم خلف ستار الواقع ذاته.. الكتاب ينقسم إلى أحد عشر مقالًا مسلسلًا يتناولون موضوعات متنوعة تنقسم ما بين الفيزياء النظرية والتكنولوجيا والطب والغرائبيات وعلوم الظواهر الخارقة للطبيعة.. مواضيع متنوعة وغريبة فعلًا، لا يربط بينها سوى أن جميعها جديد تمامًا على المجتمع العربي عمومًا، وعن ثقافته التي لا تهتم في المعتاد بأشياء كهذه ..", "/images/products/9789778201000.webp", "9789778201000", "خلف حافة الكون", 200, 150m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 204, "محمود علام", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كلما تفكرت في تلك الكلمة اكتشفت أنها عبقرية بشكل غير عادى.. عبقرية لدرجة أنها تصلح للرد على أي سؤال لا تجد له إجابة.. أى سؤال في أي زمن، وفي أي مكان.. فأحيانًا، كثرة الأسئلة التي لاتجد لها إجابة في عقلك يمكنها أن تقودك للإلحاد لو كنت ضعيف النفس أو لا تملك الإيمان الكافي للبحث عن الإجابات.. وهذا ما كاد أن يحدث معي أنا نفسي..\nالله لايرمى النرد، وبالمثل؛ لاشئ في الكون خلق عبثًا.. ليس معنى أننا لا نفهم الغرض من وجود الكون وكيفية خلقه أنه قد خلق عبثًا وبلا مغزى.. كلا بالطبع.. عقولنا دومًا ما كانت قاصرة عن فهم كيفية تفكير الإله، ولماذا خلق كل شئ.. لماذا خلق البشر والكون..\nتلك هي القضية العبثية.. كلما تقدم العلم، كلما زادت الأسئلة واكتشفت في قرارة نفسك أنه لا جواب هنالك.. كل ما يمكنك فعله هو التأمل، والتفكير ومحاولة الإستيعاب، فالأدلة موجودة في كل مكان، لكن العقول هي التي تأبى التصديق..\nتلك هي الحقيقة المؤسفة.. قبولها نضج وذكاء، ورفضها حماقة وضيق أفق.. ولكن هؤلاء يفضلون أن يكونوا حمقى على أن يكونوا بشرًا ضعفاء.. يفضلون التسليم بقوانين الإحتمالات والصدفة، وينسون أن تواجدهم في هذه الحياة، وموقعهم في هذا الكون العظيم، لا يمكن أن يكون صدفة أبدًا..\nوأن الله، أبدًا؛ لا يلعب النرد..", "/images/products/9789778201079.webp", "9789778201079", "الله لا يرمي النرد", 246, 180m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 205, "أحمد الخميسي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة \"حفيف صندل\" هي عمل أدبي يضم 30 قصة قصيرة للكاتب المصري أحمد الخميسي.\nالمجموعة تتسم بتنوع موضوعاتها وغنى أفكارها، حيث ستجد بين صفحاتها قصصًا عن الحب، وأخرى تمس الواقع السياسي، إلى جانب القصص الساخرة وغيرها من الموضوعات المتعددة.\nمعظم القصص مكتوبة بأسلوب مميز، وتترك أثرًا واضحًا في النفس", "/images/products/9789778202236.webp", "9789778202236", "حفيف صندل", 120, 120m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 206, "محمد آدم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تسرد الرواية رحلات المترجم والرحّالة سليمان، الذي بدأ مسيرته في أراضي الدولة العثمانية في القرن السادس عشر، مدفوعًا برغبة في الانتقام. قضى أكثر من ثلاثين عامًا يتنقّل بين الأقاليم الأوروبية التابعة للإمبراطورية العثمانية، خلال عهد السلطان سليمان القانوني، تلك الحقبة التي نادرًا ما يتم التطرق إليها في السرد التاريخي، رغم ما حفلت به من أحداث وتحوّلات.", "/images/products/9789778201178.webp", "9789778201178", "قلب على ضفاف الدانوب", 352, 240m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 207, "أحمد سعد الدين", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور هذه الرواية حول الرحلة التاريخية الطويلة لقلادة بابلية قديمة، يقال إنها ملعونة، تطارد كل من يرتديها، وتفضي به في النهاية إلى حتفه. من الملك البابلي الشهير حمورابي إلى الرئيس الأمريكي جون ف. كينيدي، لم تنجُ روحٌ لبستها من مصيرها المشؤوم.", "/images/products/9789778200423.webp", "9789778200423", "قلادة مردوخ", 398, 270m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 208, "أحمد عصام", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تروي الرواية حكاية شاب يُدعى فارس، يعيش مع والديه في مدينة بحرية تقع خارج حدود الزمن، مدينة لا تشبه أي مدينة حديثة. تعتمد في معيشتها على البحر، وسكانها لا يتعاملون بالنقود، بل يبادلون البحر بأثمن ما يملكون مقابل خيراته. في هذه المدينة، تُقدَّر المعرفة ويُحتفى بالقراءة، ويُعرَف عمر كل فرد من لون قميصه. أما القمر، فيتوسّط سماءهم، لكنه لا يبدو للجميع بالشكل نفسه: يراه البعض ناصع البياض، وآخرون حالك السواد، وغيرهم بلون أحمر متوهّج، وكأن القمر مرآة تعكس باطن كل شخص وتكشف مكنون روحه.\n\nورغم اختلاف أنماط العيش والعادات في هذه المدينة عن المدن الحديثة، تبقى سمة واحدة لا يستطيعون الفكاك منها: ظلّ الفقر الذي يُخيّم على الجميع.\n\nوبجوار هذه المدينة البحرية، تقوم \"مدينة الظلام\"، مكان مغمور في عتمة لا تُخترق، يبعث في نفوس من يدخله رهبة لا توصف. الانتقال إليها قرار صعب، لا يُتخذ إلا مقابل تضحية عظيمة. خريطتها تتغير من شخص إلى آخر، فلا يتفق اثنان على وصفها. هي المدينة التي \"يدفع العقل الإنسان نحوها، لكن الحكيم لا يذهب إليها.\"\n\nأما فارس، ذلك الشاب التائه بين قناعاته وأنانيته، فيحمل في قلبه حنقًا على كل شيء، ولا سيما البحر. يشعر أن البحر يُغدق كنوزه على من لا يستحق، بينما يحرمه هو مما يشتهي، فلا يمنحه سوى أوراق ممزقة وأشياء بالية في شباكه، كلما تطلع إلى رزق أو أمل. ومع كل خيبة، تتعمق مراراته، ويشتد توقه إلى الثروة والسلطة والتحكم، حتى يبدأ بخسارة أشياء ظن يومًا أنها ثابتة في حياته.\n\nتطرح الرواية سؤالًا جوهريًا:\nهل سينتصر رضا فارس على أنانيته؟\nهل سيستفيق قبل فوات الأوان، أم أن الجشع سيكون مصيره الأخير؟", "/images/products/9789778201116.webp", "9789778201116", "أرض الغربان", 168, 120m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 209, "أحمد الزناتي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لفت نظري منمنمةٌ فارسية ضخمة، تشغل مساحة واسعة من الجدار المقابل لمكتبه. كانت عبارة عن بساطٍ منسوجٍ في كاشان، مطرّزٍ بأوراقٍ نباتية وأزهار. بدا البساط بلون فيروزي، كأنه محيطٌ يرتدي فستانًا من الزهور الزرقاء. تتوسطه صورة شيخ كثّ الشعر، أبيضه، يجلس في ظل شجرة عملاقة، وخلفه جدول ماءٍ تحوم حوله طيور ملوّنة.\n\nكان الشيخ شاخص البصر إلى السماء، رافعًا يده اليمنى كما لو كان يتضرع بالدعاء، بينما تمسك يده اليسرى كأسًا.\n\nوقد ذُيِّل البساط بعبارة مكتوبة بخطٍ فارسيٍ واضح:\n\n\"لوّنْ البساطَ بالخمرِ إنْ أمركَ شيخُ المجوس،\nفالشيخُ العارفُ هو الأعلمُ بمسالكِ المنزل.\"", "/images/products/9789778201147.webp", "9789778201147", "البساط الفيروزي", 288, 215m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 210, "السعيد الخيز", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يحدث أَنِّي أرغب فِي قول شَيْء مَا لذاتي خصوصًا، تأتي الرياح وتأخذ أفكاري بعيدًا عني وترميها فِي بحر النوتات الشاردة، ها أنا أحمل جسدًا وَهَذَا الجسد بحمل ندوبًا وَهَذِه الندوب تحمل ذكرياتٍ، وَهَذِه الذكريات أليمة، صور من الدم والنار والعبث والقهر والفقر والبراءة، ها أنا أحمل جسدًا أَوْ يحملني جسد مطبع بملصقات لأفلام قديمة كَمَا عَلَى واجهة سينما الصحراء ، أريد أن أعيش ملثما حَتَّى لا تدركني المساءات الحزينة بعد اليوم، أنا من أصفياء المواجع والمراثي، لا أريد أن أموت الآن، مَا زلت أريد اختبار الفرح إن كان يليق بِي. إِنَّهُ يليق بِي. لقد عشت حياة هادئة جدًّا، لا شيء يعكر صفوها غَيْر بعض القلق اليومي والأرق الَّذِي يزعجني كُلّ ليلة. هَذَا الجسد المكابر الَّذِي سنَّ لنفسه طريقًا أخرى وبدأ يأكل بعضه. يَقُول الطبيب إن بعض الخلايا تأكل الأخرى. الأمر غريب. أنا آكل نفسي. رموشي تنغلق عَلَى أَيَّام عشتها وأنا أراهن عَلَى جودتها. صنعت لنفسي عالمًا جميلًا، لا أحد يَسْتَطِيع أن ينكر ذَلِكَ.", "/images/products/9789778201154.webp", "9789778201154", "إبن الصلصال", 288, 215m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 211, "عمرو العادلي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أتذكّر ملامح أمي، ويكفيني أن أستحضر صورتها حتى تهبّ إلى روحي رؤى دافئة، محبّبة، من زمن لم أعشه يومًا — زمن تعرفه الأحلام، لكنه غريب عن حياتي المحدودة، تلك التي لا أستطيع فيها سوى لمس الأشياء والناس. أنادي بأسماء سرعان ما أنساها، كأنها لم تكن، ثم أتيه في ذهولٍ يشبه السكر، لا أدري أين أنا، ولا ما الذي ضاع مني.", "/images/products/9789778200133.webp", "9789778200133", "الزيارة", 208, 150m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 212, "ضحى صلاح", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذه الرواية النفسية الاجتماعية، تنسج الكاتبة ضحى صلاح حكاية مؤلمة لفتاة شابة عانت لسنوات من القهر وسوء المعاملة، حتى وجدت نفسها في مواجهة مصير مأساوي يعتصر القلب. ومن خلال عيون \"آروى\" — الفتاة التي تخلى عنها كل من أحبت — نستكشف عوالم الفقد القاسي، والوحدة العميقة التي تخلّفها الخيبات.", "/images/products/9789776376366.webp", "9789776376366", "سهم غرب", 134, 120m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 213, "عزة رشاد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذه المجموعة التى تضم 22 قصة تظهر الوجوه المتعددة للحب والغيرة واللوعة والفقدان، مع التركيز على قضايا المرأة ومعاناتها. إضافة إلى وجوه الموت، مع استنطاق التكنولوجيا بداية من التواصل الاجتماعي وحتى أدوات القتل، فتبرز الحاجة لغاندي وحمائمه: «رسالة السلام»، مع اجتراح المسكوت عنه دون فجاجة.", "/images/products/9789778200096.webp", "9789778200096", "حائط غاندى", 158, 120m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 214, "أحمد الخميسي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بكِ. أناولك الأكواب. لا تأخذينها من يدي. لا تضعينها قرب الحوض. أظل واقفًا خلفكِ أخفق مضطربًا من الشريان الذي فى رقبتك. أطبع قبلاتي على أذنكِ الصغيرة الدقيقة. أرتدي ملابسي لأتجه إلى عملي. أنتِ لن ترافقيني حتى باب الشقة. ستظلين جالسة على المقعد بنظرة شاردة. أرجع متأخرًا في المساء ممتلئا بغرامي بك. نتناول العشاء، أنا وأنتِ بقلق ومحبة وعزلة مؤلمة. نتنشق رائحة الخبز الساخن فوق المنضدة. ذكريات في طريقها إلى النوم تتقلب على السرير. ينتهى يوم طويل جعلنا جزءًا من ذكرياته. يخطر لي أن المخيف في الموت هو الوحدة. مسيرة المرء بمفرده في ذلك الوادي. ذلك لن يخيفنا لأننا معًا. أنا وأنتِ. لأنه كانت لنا لحظات مشبعة بالغرام والعذوبة، بالهواء الذي يتدفق من الشرفة بلون المساء مؤرجحًا أطراف الستارة البيضاء.\nأتملى وجهك بحب وعمق ويأس في حجرة النوم. تمدين بصرك من فوق كتفي إلى صوان الملابس. تهبطين برأسك إلى الوسادة. تطفئين المصباح الصغير. يظل قلبي متيمًا بكِ وفيه أمل لا ينتهي. فقط لو تقولين لي مَن ِمِنا الذي مات ولم يعد يرى الآخر؟", "/images/products/9789776376830.webp", "9789776376830", "أنا وأنت", 168, 120m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 215, "محمد أدم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور الأحداث في القرن الرابع الهجري (العاشر الميلادي)، تُسلّط الضوء على مِصر في العصر الفاطمي، في عهد الخليفة \"المُعِزّ لدين الله الفاطمي\"، وتصوّر الحياة الاجتماعية والسياسية وقتئذ، كما تُبرز قوة الدولة داخليًّا وخارجيًّا، وكيف أحكمت السيطرة بقبضة مِن حديد على مقاليد الأمور في ديار مِصر والمغرب والشام، كما تتناول الأحداث معاناة المجتمع المِصري بكل أطيافه بسبب ممارسات أصحاب المذهب الإسماعيلي (مذهب الفاطميين).\nومن الشخصيات المهمة في الأحداث؛ الخليفة الفاطمي \"المُعِزّ لدين الله\"، الأمير \"تميم بن المُعِزّ\" (الشاعر)، القديس \"سمعان الخرّاز\"، الوزير \"جعفر بن الفرات\"، الوزير \"يعقوب بن كِلّس\"، البَطْرَك \"إبرام ابن زرعة السرياني\".", "/images/products/9789778202700.webp", "9789778202700", "وصارت القاهرة", 376, 290m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 216, "أحمد صبري ابوالفتوح", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "فى برسكال نحن بصدد \" حدوته كاملة\" نشارك فى إعادة صنعها وفقا لما يراه الراوى العليم فى الغالب الأعم، ومع ذلك يمكن للقارىء المحترف أن يتحمل اختيارات الروائى التى لا توافق رؤيته مقابل الرغبة في معرفة كيف انتهت الحدوتة إلى تحول عربجى شقى إلى ولى من أولياء الله الصالحين، تبدأ الرواية فى مقام \" سيدى عبد العاطى زمش \" القابض على اللجام، الضارب بالكرباج\"، وهى ألقاب تقدم لنا تفسيرا لكيفية \" أسطرة\" الأفعال العادية \" لعربجى مطرود من رحمة أسرته وكيف تتحول أفعاله العادية جدا بل والبائسة إلى كرامات، كل ذلك بفضل \" برسكال\" ابنته من زوجته \"غاية المنى إبليس\" التى اشتهرت بالسحر و بقدرات خارقة", "/images/products/9789778202830.webp", "9789778202830", "برسكال", 324, 245m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 217, "محمد عصمت", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بدأ الحكايات على ضهر الحوت.. وتنتهي الحيوات\nوتنكشِف أسرار لا تعرِف الحدود بين الواقِع والخيال.\nلابُد من وجود بعض الأشياء الضروريَّة لكي توجَد جريمة قتل مثل أداة الجريمة، ومسرَح الجريمة، والجُثَّة، والقاتِل، والدافِع.\nحسنًا، الأمور مُعقَّدة هُنا قليلًا، فلدينا جريمة قتل يجِب حلِّها في أسرَع وقت مُمكِن، لكِن هُناك مُشكِلة صغيرة للغاية، لا توجَد أداة جريمة، ولا مسرَح جريمة، ولا جُثَّة طبعًا، وبالتالي لا قاتِل، ناهيك عن جهلنا بالدافِع.\nودورك، هو مُساعدة سعيد، فرد الأمن المسكين، على حل هذه الجريمة، قبل فوات الأوان! وقبل ضرَب القاتِل مرَّة أخرى! أو حدُوث ما هو أسوأ من ذلِك!", "/images/products/9789778202847.webp", "9789778202847", "ضهر الحوت", 214, 190m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 218, "عمرو المنوفي", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"كل ما تخشاه يكمن هناك... في أعماق الدارك ويب، وبداخل تلك الصناديق المشؤومة.\"\n\nعالم الانترنت، عالم مخيف، وأخطر طبقاته هي الانترنت المظلم، حيث كل شيء ممنوع، ومحرم، وخطر، متاح.\nولكن مالا تعرفونه، أن هناك طبقتين إضافيتين، لا يعلم عنهم إلا عدد لا يتجاوز أصابع اليد الواحدة في العالم كله، وتلك الطبقتان تحتويان على ما لا يخطر على بال كائن حي من أسرار وأهوال.\nمعا سنكتشف ما يوجد في (القبو).\nوفي الطابق الشبحي.\nوفي الصناديق المظلمة، التي يحتوي كل منها على لعنة رهيبة، أو سر مغلق، أو ....\nالكثير سنكتشفه معًا.", "/images/products/9789778202823.webp", "9789778202823", "الصناديق المظلمة", 272, 220m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 219, "ميخائيل عماد", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في يومه الأول للسكن في كومپاوند (پالم تاون) يجد ماهر اللص السابق جثة في بانيو الفيلا الخاصة به٬ كما أن تتم سرقة تمثال أثري يُمثل نصف ثروته من المنزل.\n\nفي الوقت نفسه الذي تتعرض فيه (ريم) الشابة الكفيفة من سكان الكومپاوند إلى مواجهة مع القاتل٬ وتتلقي تهديدًا بالقتل كي تتوقف٬ حتى يُقتل قطها وصديقها الوحيد شلبي٬ مما يدفعها إلى مواصلة البحث خلف القاتل.\n\nيبدأ كل من (ماهر) و(ريم) في البحث عن القاتل صاحب رمز (الفيل) كل على حدى في خطوط متوازية٬ وسط الأغنياء والممثلين وصفوة المجتمع٬ وكلما تتبع واحد منهم خيط أو توصل إلى دليل٬ زاد الأمر تعقيدًا.\n\nحتى تتكشف حقيقة القاتل٬ أو الرجل الذي يقع خلف جرائم القتل للدقة٬ والذي يقوم بخطوة ومجنونة ويغلق أبواب الكومپاوند ويقطع الاتصالات٬ آمرًا السكان بقتل بعضهم البعض في محاولة للنجاة.", "/images/products/9789778202625.webp", "9789778202625", "الخريف في بالم تاون", 410, 290m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 220, "يحيى صفوت", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما الغريب في صالون حلاقة به كرسي واحد، حلاق واحد وزبون واحد، لكنه بلا مرآة؟ ربما لأنه لم يكن هنا بالأمس، ولن يكون هنا غداً، ربما لأنني أشعر أنه… يطاردني.", "/images/products/9789778202632.webp", "9789778202632", "صالون غريب", 240, 190m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 221, "احمد عثمان", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مهندسة ديكور في منتصف العمر تتورط في جلسة تظنها لتحضير الأرواح لتشاهد فجأة حب عمرها! فتتغير شخصيتها شيئًا فشيًا حتى يناديها قصر في عزبة نيلية لترميمه وهناك تتغير أكثر فأكثر حتى تصبح شخصً أخر أقرب إلى سيدة هذا القصر القديم.\n\nفهل ما شاهدته هو الحقيقة؟\nأما أنها مريضة نفسية كما يدعي زوجها تهرب من حقيقة حادث أليم تحاول أن تتناساه.", "/images/products/9789778202618.webp", "9789778202618", "روحي فيك", 256, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 222, "مصطفي نصر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رواية تغوص في عالم الإسكندرية لتكشف المسكوت عنه من مؤامرات ودسائس ومصائر عديدة لشخوص مأزومة..\nتبدو الشركة التي يعمل فيها الشخوص كأنها عالم مصغر لا يخلو من المفارقات العديدة التي تشكل روح هذا النص، وتقترب بقوة من عالم السطوة وراس المال..\nفي ستينيات القرن الماضي تولد هذه الاحداث، لكنها لا تقترب من الاحداث التي شكلت مفاصل الدولة في ذلك الوقت، إذ أن هم شخوصها الأساسي هو لقمة العيش، بحث مستمر ودؤوب ومصائر مختلفة وحكايات تتشكل وتتوالد من رحم المعاناة..", "/images/products/9789778202786.webp", "9789778202786", "معاش مبكر", 224, 190m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 223, "دينا هيكل", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتلقى يُوسُف وزين رسالة من صديقهما القديم آدم، يدعوهما إلى لقائه قريبًا. كانت الرسائل مفاجئة، ولكنها كانت خطافًا يمكنه أن ينشلهما من حياة محاصرة رتيبة. يطلب منهما آدم العمل معه على حلم قديم لهم. اختراع يعد بثورة ستغير مفهوم تحقيق العدالة، العدالة التي لم يجدوها في ماضيهم. آلة ستعطي الموتى فرصة أخيرة لكشف أسرارهم. لكن سيؤدي سعيهم إلى سلسلة من الفوضى حيث يجبرون على مواجهة تداعيات أفعالهم، ومطامع الآخرين، وعدو لم يكن بالحسبان. تتلاشى الحدود بين الصواب والخطأ، والحقيقة والخيال، حتى يتشوه مفهوم العدالة نفسه، ويجدون أنفسهم أمام معضلة أخلاقية.\nكم من التضحيات ستطالب بها الآلة من أجل الوصول للحقيقة وتحقيق العدالة، وهل هناك حدود للثمن الذي سيدفعون من أجلها؟\nسيواجه شخص آخر في زمن آخر المعضلة نفسها، حيث سيقوده لقاؤه بآلة الموتى إلى طريق مظلم محفوف بالمخاطر يهدد حياته، لكنه الوحيد الذي يمكنه تحقيق العدالة لضحية جريمة قتل مريبة.\nزمنان مختلفان، نفس الأسئلة، ولكن هل يصلون لنفس النهاية؟", "/images/products/9789778202762.webp", "9789778202762", "اّلة الموتى", 200, 175m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 224, "شريف ثابت", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عشية عيد ميلاده تم تكليفه بمهمة عمل ميدانية اضطرته للخروج إلى العالم لأول مرة بعد سنواتٍ طوال قضاها بين جدران المكاتب وقاعات الاجتماعات.\nهناك في أقصى الجنوب سيتعين عليه أن يتسلق جبلًا شاهقًا قديم قِدَم الدهر، يتطير منه الأهالي وبتجنبون الحديث عنه.\nغير أن رحلة العمل التي اعتقد أنها ستحقق أحلامه تحولت إلى كابوس حين اكتشف أنه عاجز عن الهبوط من الجبل والعودة إلى عالمه، وأن من يحتجزه هناك بالأعلى هو الجبل الأسطوري المخيف نفسه (!) والذي كان ينتظره منذ أمدٍ بعيد كي يلعب معه لعبة خطرة خارج حدود أي منطق.\nفي منطقة غائمة بين اليقظة والحلم، الحقيقة والوهم، الوعي واللاوعي، تدور أحداث أخطر وأعظم مغامرة يمكن أن يخوضها الإنسان، حيث سيتعلم أن رحلته إلى العالم الخارجي الفسيح هى في حقيقتها رحلة إلى الداخل، في ظلمات عالمه الداخلي، حيث تكمن أسرار الذات المحجوبة عن الوعي بألف حجابٍ وحجاب", "/images/products/9789778202731.webp", "9789778202731", "اللعب مع الجبل", 138, 140m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 225, "احمد صلاح المهدي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في عالم دمرت الحرب النووية غلافه الجوي، حيث تشكل الشمس تهديدًا قاتلًا لكل الكائنات\nالحية في ظل صيف نووي قاسٍ، يعيش عمر في ملجأ آمن تحت الأرض. مدفوعًا بفضول لا\nيُشبع ورغبة ملحة في استكشاف العالم خارج الملجأ، يخرج إلى أطلال القاهرة ليجد نفسه عالقًا\nفي صراع شرس بين جماعات سرية تسعى للسيطرة على تكنولوجيا يمكنها أن تحدد مصير\nالبشرية. في رحلة محفوفة بالمخاطر، يكتشف عمر أسرارًا مذهلة حول ماضيه، ويواجه\nتحديات هائلة وخيانات محتملة. في قلب هذه الفوضى يدرك عمر أن عليه اتخاذ قرار مصيري\nقد يغير مستقبل البشرية إلى الأبد.", "/images/products/9789778202649.webp", "9789778202649", "أبناء القيامة", 242, 190m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 226, "محمد عبدالمحسن", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لوحةٌ مُرعبة ليس لا مثيل، تتحرّك أجزاءُها لتُنبأ باستيقاظ شرٍ قديم من سُباتٍ طويل ليسترجع مكانته على عرش الأرض. وإرثٌ ملعون ينحدر من سلالة تعود لعُمق التاريخ، هو خط الدفاع الأخير للجنس البشري. وبين هذا وذاك يقف (علاء)، لا يفقهُ شيئًا مما يدور من حوله سوى أن على عاتقه يقع الأمر برمته، فقط لأنه الوريث الوحيد لعائلةٍ حافظت على السر لمئات السنين ... والآن قد حان دوره ليُكمل المسيرة، أو يضع كلمة النهاية لهيمنة البشر على هذا الكوكب.", "/images/products/9789778202663.webp", "9789778202663", "سرمدي", 306, 245m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 227, "أحمد عصام الدين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تروي الرواية أربع قصص مترابطة تمتد عبر ثلاثة فصول، وهي قصص نُوح، ماريا، ليلى، والراوي.\n\nقصة نُوح:\nيعود الراوي إلى طفولة نُوح الساعي، حيث كانت حياته مليئة بالتنافس مع أخيه مراد، الذي كان المفضل لدى والدهما. منح الأب مراد اسمه ومهد له الطريق ليصبح طبيبًا ويرث لقبه وعيادته، بينما تُرك نُوح بعيدًا عن الاهتمام والتقدير.\n\nقصة ماريا:\nتخضع ماريا لثلاث جلسات علاجية مع الطبيبة النفسية نادين، حيث تعترف بمعاناتها من اكتئاب لا تستطيع الأدوية تهدئته. تحكي عن طفولتها التي عاشتها وسط والديها اللذين لم يحبا بعضهما ولم ينفصلا، مما جعلها تعيش في صراع دائم بينهما، وكأنها خيط ضعيف يتأرجح بين طرفين يحاول كل منهما شده وتمزيقه.\n\nقصة ليلى:\nتنتقل ليلى إلى بلدة صغيرة مع والدها جميل وأختها عزة، التي تعاني من متلازمة داون. يستأجر والدها متجرًا صغيرًا بجوار بورصة الساعي وشقة بسيطة بأثاث قديم. سرعان ما يصبح جميل أشهر صانع حلويات في الشارع، بينما تكبر ليلى وتقع في حب جارها مصطفى، الذي يعرّفها على عالم الكتب والقراءة. لكنه يغادر فجأة إلى القاهرة دون أن يودعها أو يشرح سبب رحيله.\n\nقصة الراوي:\nيرسل الراوي ثلاث رسائل إلى ناشره، يعبّر فيها عن اكتئابه ورغبته في التوقف عن الكتابة نهائيًا. يروي كيف كان يحمل حقيبته القديمة في رحلاته إلى القاهرة، بحثًا عن من يقرأ كلماته أو يدعمه، وكيف أصبحت شقته فارغة بعدما تركته زوجته، التي كانت تكره الورق، وابنته، التي لم يمنحها من وقته بقدر ما كان يمنح لشخصيات رواياته.\n\nقصص تتشابك بين الحب والفقد، بين الأحلام والخيبات، في عالم يملؤه الصراع والتحديات.", "/images/products/9789778202328.webp", "9789778202328", "دوائر الساعي", 152, 130m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 228, "ميخائيل عماد", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "علاء مدبولي، الكاتب الشهير، يسافر إلى الإسكندرية هربًا من قصة حب فاشلة، وبحثًا عن فكرة جديدة لروايته القادمة. هناك، يتلقى دعوة غامضة من حارس مبنى الشقق المجهول (ميرتل)، الذي ظهر فجأة وأثار تساؤلات كثيرة بين أهل المدينة. بدافع الفضول، يقبل علاء الدعوة، آملاً أن يجد بين جدران المبنى قصة تستحق أن تُروى.\n\nخلال العشاء الأول، يكشف له مالك المبنى سرًّا مذهلاً: جميع سكانه مسافرون عبر الزمن من عام 1898، وهو عام مفقود من التاريخي. لقد جاءوا إلى الحاضر بناءً على نبوءة تؤكد أن علاء وحده قادر على إيقاف قاتل إنجليزي متسلسل قتل 12 فتاة شابة خلال أربع ليالٍ من ذلك العام المنسي. مهمته هي العودة إلى ذلك الزمن ومنع القاتل من ارتكاب جرائمه وإنقاذ ميرتل، ابنة مالك المبنى وأحد أقارب السكان.\n\nفي المقابل، سيُمنح علاء فرصة نادرة لتغيير حدث تاريخي واحد. يوافق على المهمة، مدفوعًا برغبته في العودة بالزمن ليس فقط لإنقاذ ميرتل، بل أيضًا للهروب من مصيره المحتوم وخيانة خطيبته إيمي، التي تركته.", "/images/products/9789778202342.webp", "9789778202342", "أثر اليعسوب", 368, 260m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 229, "أحمد صلاح المهدي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث الرواية في عالم خيالي يتمحور حول قرية تقع على جانب التل، ولذلك يُطلق عليها سكانها اسم \"جانب التل\". تحيط بها غابة شاسعة من الأشجار العملاقة تُعرف باسم \"غابة الظلال\"، ويؤمن أهل القرية بأنها نهاية العالم، وأنه لا يوجد شيء وراءها. في قلب القرية، توجد أطلال قديمة تحمل نقوشًا غامضة لم يتمكن أحد من فك رموزها.\n\nبطل الرواية شاب يُدعى بارسينو، وُلِد مصابًا بالمهق، فكان له شعر أبيض، وبشرة بيضاء، وعينان زرقاوان. بسبب مظهره المختلف، نبذه أهل القرية وأطلقوا عليه لقب \"طفل اللعنة\"، معتقدين أنه وُلِد دون بركة الشمس. فهم يؤمنون بأن الشمس والقمر والنور هم حُماة القرية من الظلام والمخاطر الكامنة في غابة الظلال.\n\nلا يجرؤ أحد على دخول الغابة سوى حطّاب عجوز يُدعى أوركين، الذي يجلب الحطب للقرية. ومن هنا، يقرر بارسينو، برفقة صديقه أكينو، اكتشاف سر هذا الحطّاب ومعرفة ما يخفيه عن الغابة الغامضة.", "/images/products/9789778202403.webp", "9789778202403", "لعنة جانب التل", 396, 270m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 230, "مصطفى نصر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث الرواية خلال فترة الاحتلال الإنجليزي، حيث تركز على أحياء معينة في الإسكندرية وما يجري داخلها، سواء تحت أعين الاحتلال أو بعيدًا عن رقابته، متضمنة أنشطة مشبوهة. تستعرض الرواية دور كل شخصية في تشكيل هذه الأحداث وتأثيرها على مجرى الأحداث داخل هذه الأحياء.\n\nيأخذنا الكاتب مصطفى نصر في رحلة داخل العالم الخفي للبغاء في الإسكندرية، كاشفًا عن الفساد العميق الذي يسري في أوصال المجتمع. يسلط الضوء على تواطؤ الساسة الذين حموا هذا الانحلال، ومعاناة أولئك الذين دفعتهم الأقدار إلى هذا المصير القاسي.\n\nورغم قسوة الأحداث وبؤس تفاصيلها، ينسج الكاتب حبكة مشوقة، تمزج بين شخصيات حقيقية من التاريخ وأخرى من خياله، ليخلق رواية تنبض بالحياة، تجمع بين الواقع والخيال في سردٍ ممتع ومؤثر.", "/images/products/9789778202380.webp", "9789778202380", "غواني الإسكندرية", 184, 140m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 231, "محمد محمد مستجاب", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"الفتي \"\" محمد \"\" وشهرته \"\"حمامه\"\" في الرابعة عشرة من عمره، موهوب موهبة استثنائية في لعب كرة القدم، ودائمًا ينظر للاعب الشهير \"\" محمد صلاح\"\" بأنه مثله الأعلى، ويتمني أن يصبح مثله لاعبًا شهيرًا وعالميًا، لكن بسبب فقره وفقر أسرته تفشل جميل محاولاته في الالتحاق بنادي شهير، لأن هذا يحتاج إلى نقود وعلاقات وهو لا يمتلكها.\nمن جهة أخري تفاجأ أسرة \"\" حمامة\"\" بقدوم المعلم \"\" أبو أيمن\"\" صاحب السبعين عامًا. وهو تاجر ثري يسكن بالحي وصاحب البيت الذي يسكنون فيه، ويطالب بالزواج من أخت حمامة \"\" وفاء\"\" ذات السبعة عشر عامًا، والتي تذاكر ليل نهار من أجل الحصول على الثانوية العامة ودخول كلية الطب.\nترفض الأسرة طلب المعلم أبو ايمن الغريب، إلا أنها تفاجأ بتهديده بطرد الأسرة من بيته لأنه يريد أن يهدم البيت ويقيم مكانه عمارة سكنية كبيرة، كما يطالب بالنقود – الكثيرة – التي اقترضتها منه الأم، منذ سفر زوجها إلى ليبيا للعمل هناك، واختفائه.\nيمهل المعلم أبو ايمن الأسرة شهرًا لسداد نقوده أو تقديم الكمبيالات للشرطة من أجل القبض على الأم.\nتشعر اسرة حمامة بالضياع، وتصمم الأم على حماية اسرتها مهما كلفها ذلك، فهي تعمل – بائعة خبز – من أجل سداد متطلبات أسرتها.\nيفكر الطفل حمامة كيف يساعد أسرته، ويخبر امه بانه يستطيع العمل على توك توك من أجل مساعدة الأسرة وسداد ديوان المعلم أبو ايمن، وكي يحمي أخته وفاء من هذا الرجل الغاشم الذي يريد ان يتزوجها وهي في عمر احفاده.\"", "/images/products/9789778201888.webp", "9789778201888", "البيانو الصغير", 140, 120m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 232, "أحمد صبري ابوالفتوح", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"فى تلك الرواية «تاريخ آخر للحزن» يستخدم الكاتب العديد من التقنيات السردية المميزة والمبتكرة والشيقة ليصل بالقارئ إلى حالة نفسية معقدة، لا يمكن وصفها بسهولة هل هى المتعة أم الحزن أم الألم، خاصة وهو يتتبع مسار نحو أربعة أجيال فى قرية بسيطة هى نوسا البحر، بادئا بحدث يشابه السير الشعبية والبطولات الفردية النادرة التى يضحى فيها شخص أو شخصان من أجل حياة الجميع. هذا هو الحال بعد هزيمة عرابى وانتشار الإنجليز فى القرى والوسيات والأبعديات المختلفة لتصفية أسر الذين شاركوا فى جيش عرابى، من خلال قائمة يمتلكها القائد الإنجليزى، حرقوا قرى وأبادوا أهلها ودمروا العديد من الوسيات والأبعديات قبل أن يصلوا إلى نوسا البحر، التى كانت تعانى من أزمة حادة فى الغذاء لدرجة اضطرار الأهالى لأكل بقرة يقال إنها كانت ميتة. ثم يحتار الرأى بين الفرار من القرية وبين الاختباء حتى يمر عساكر الإنجليز، ويقرر الشيخ حسنين اللهفة وحلاوية زوجة فتح الله، والتى انتظرت عودة زوجها من جيش عرابى بلا جدوى. يتم التنكيل بهما وسحلهما وتعذيبهما ثم قتلهما بلا رحمة، لتترك حلاوية ابنها رضيعا يحصل على غذائه من كلبة.\nالأسرة الرئيسية فى الرواية هى أسرة إقطاعية «أسرة أرسلان» وعميدها عبد الباسط أرسلان، وهى عائلة تمتلك سرايا كبيرة وأبعديات فى نوسا البحر وما حولها، كما يمتلك أفرادها العديد من المقومات السلطوية والنفوذ، وإن كان هناك خلاف بين عبد الباسط أرسلان وإخوته إلا أن هذا الخلاف غالبا ما ينزوى جانبا ولا يظهر إلا كمبرر درامى لإحباط ابنه منجى أرسلان، المحامى الحقوقى، الذى يهيم عشقا بابنة عمه إلا أن عمه يرفض تزويجه من ابنته نظرا لميول «منجى» الناصرية، وغضب والده وأسرته من تلك الميول بعد أن تسبب عبد الناصر فى خسارة الأسرة الكثير من أملاكها، باعتبارها من كبار العائلات الإقطاعية فى المنصورة. فأصبح منجى بمثابة الابن الضال العاق الذى يفكر عكس اتجاه تفكير الأسرة، إنه الابن المتمرد الذى يدفع ثمن تمرده سنوات فى السجن بتهمة سياسية متنوعة.\n\"", "/images/products/9789778202373.webp", "9789778202373", "تاريخ آخر للحزن", 376, 270m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 233, "أحمد صلاح سابق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتابع الرواية سلسلة من التفجيرات الإرهابية التي تنفذها جماعة إسلامية متطرفة في بريطانيا، لتقود إلى قرار صادم: نفي جميع المسلمين البريطانيين إلى جزيرة نائية محاطة بأسوار عالية. تُترك هذه الجماعة لتدير شؤونها بنفسها، لكن الجزيرة سرعان ما تغرق في الفوضى. بلا خدمات ولا قوانين، ومع تصاعد العنف، تتحول الجزيرة إلى مكان خطير تسيطر عليه العصابات والمجرمون، حيث يصبح البقاء للأقوى والأشد قسوة.", "/images/products/9789778201475.webp", "9789778201475", "الغثاء", 400, 250m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 234, "مجيب الرحمن مدحت", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تأخذنا الرواية في رحلة تبدأ من قوم عاد ومدينة إرم المفقودة، حيث تعجّ الأرض بالآلهة المتعددة، والجن، والحروب، والظلم. في زمنٍ اختلطت فيه تقاليد البدو والحضر، يمرّ السرد بمنعطفات خطرة، وينتهي عند \"عيسى بن العبّاس\"، ليربط الماضي البعيد بلحظات مفصلية من التاريخ الإسلامي.\n\nنصل إلى \"إرم ذات العماد\" — أسطورة الجمال العربي، \"أتلانتس العرب\" — فنمشي بين جناتها، ونرى قصورها، ونلتقي بشعبها من الإنس والجن.", "/images/products/9789778201390.webp", "9789778201390", "وداعًا إرم", 458, 290m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 235, "مجيب الرحمن مدحت", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في مزيج ساحر يجمع بين زمن الخلفاء والعصر الحديث، يقدم الكاتب حكاية آسرة ومفعمة بالإثارة.\n\nتبدأ الرواية بجريمة شنيعة يقترفها أحد الخلفاء، لتُشكّل لحظة الانطلاق لأحداث تمتد عبر الأجيال. ينتقل السرد لاحقًا إلى \"آدم النصيري\"، العائد إلى وطنه للمرة الأولى، حيث يغوص في إرث عائلته العريقة، كاشفًا بذلك ذكريات مطمورة طواها النسيان.\n\nبأسلوب سردي محكم، ينسج الكاتب مسارات الشخصيات ضمن دائرة واحدة، ليقدّم رواية مشوّقة تملؤها الغموض والتشويق، وتمسك بالقارئ حتى الصفحة الأخيرة.", "/images/products/9789776376874.webp", "9789776376874", "قلب النصيري", 290, 180m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 236, "هدى أنور", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مخطوطة بنيامين هي رواية تاريخية تتقاطع فيها إحداثيات الزمان والمكان، بدءًا من زمن سيدنا يعقوب وابنه بنيامين، الذي تُروى حكايته انطلاقًا من الجد الأكبر إبراهيم، أبو الأنبياء، وصولًا إلى يومنا هذا، حيث يرقد مقام بنيامين في حي الحيدان بمدينة الموصل، على ما يُعرف بـ\"الطريق الأحمر\".\n\nتبدأ الرحلة من مدينة أور، الواقعة على الضفة الغربية لنهر الفرات، في اللحظة التي بلغ فيها الأمر الإلهي ذروته في الكون، ودوّى نداء النبوّة، مرورًا بأطلال قُمران في الأردن عام 1947، حين عثر الراعي مجتبى، في بحثه عن إحدى عنزاته الضائعة، على مخطوطة مدفونة بين الصخور، لتنتهي عند الطريق الأحمر، حيث يسعى خالد الإكيابي إلى فكّ شيفرة مخطوطة بنيامين، سابرًا أغوار التاريخ، ومستكشفًا أسرارًا حُجبتها الرمال وطمستها الأزمنة.", "/images/products/9789778201383.webp", "9789778201383", "مخطوطة بنيامين", 336, 220m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 237, "خالد زيدان", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يعتز الفنان دومًا بتلك الرؤية من أعلى نقطة، حيث تنجلي التفاصيل وتتكشف الأسرار. فالوقوف في العلو يمنح فرصة أوسع للحُكم على المشهد بحياد تام. وفي لحظة عابرة، تقرر أن تشتري تذكرة ذهاب وإياب إلى عقول العابرين: ماذا يفعلون؟ من أين جاؤوا؟ وإلى أين يمضون؟\n\nوكانت المفاجأة أنني اكتشفت أننا جميعًا مصابون بحالة من الحُبسة الكلامية، نعجز عن التعبير عمّا يعتمل في داخلنا، كأن اللغة قد خذلتنا، أو أن الكلمات لم تعد تكفي.", "/images/products/9789778201550.webp", "9789778201550", "أفيزيا", 226, 150m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 238, "شريف شعبان", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يروي لنا الدكتور ماكلين، من خلال مذكراته، رحلته عبر الأمة العبرية، وغوصه في أعماق المجتمع الإسرائيلي وأسراره؛ ذلك المزيج الغريب من الشعوب والثقافات، وتأثيره العميق على العرب القاطنين في المناطق القريبة، بل وداخل الأراضي المحتلة نفسها.", "/images/products/9789776376694.webp", "9789776376694", "بنت صهيون", 238, 150m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 239, "السعيد الخيز", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "4 شبان مغاربة في رحلة بحث عن أنفسهم ! في الممر المظلم الذي يربط ساحة الاندلس بالرحبة القديمة ومسجد سيدي وسيدي بمدينة تارودانت، يقع منزل سي علال. وفي الطابق السفلي الرطب يوجد بيت الطلاب، أبطال الرواية. بيت يتكون من غرف ثلاثة تأوي جدرانها أربعة شباب، تلتقي الأجساد في تلك البقعة وتهيم الأرواح في أفلاكها، كل روح في عالمها الخاص.", "/images/products/9789778200355.webp", "9789778200355", "قطف الجمر", 240, 170m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 240, "مصطفي عبيد", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حسين توفيق صبي صغير يعيش في حي المعادي ويكون فرقة من الصبية لاغتيال جنود الإحتلال البريطاني في مصر قبل أن يلتقي بأنور السادات ضابط الجيش ليعيد تعليمه مبادئ الوطنية، ويدفعه لاغتيال ساسة مصريين.\n ينجح التنظيم الصغير في اغتيال أمين عثمان، ويتم تهريب توفيق إلى سوريا ليؤسس تنظيما آخرا يحاول من خلاله اغتيال رئيس الدولة. ويُحكم عليه بالاعدام وينجو بسبب انقلاب ضد نظام الحكم السوري ويعود لمصر فيحاول اغتيال الرئيس عبد الناصر ويقبض عليه ليحكم عليه بالسجن الأبدي. وهناك يكتشف أنه كان دائما أداة لقوى أخرى استخدمته باسم الوطنية.", "/images/products/9789778200508.webp", "9789778200508", "نيتروجلسرين", 310, 215m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false }
                });
        }

